import type { LaunchGuide } from '@/data/launch-guides';
import { mobilityIndex } from '@/lib/mobility';
import { getAllAniimos } from '@/lib/aniimo';
import { ELEMENTS } from '@/lib/aniimo-ui';
import { sourceById } from '@/data/sources';
import { getNovemberEventBlocks, getNovemberSupportBlocks, getNovemberFixBlocks, getNovember12Blocks } from '@/data/november-guide-updates';

export function getPartTwoGuide(locale: string, slug: string): LaunchGuide | undefined {
  const t = (en: string, hans: string, hant: string) => locale === 'en' ? en : locale === 'zh-Hant' ? hant : hans;
  if (slug === 'aniimo-pre-registration') return {
    title: t('Aniimo Launch Rewards: Check Eligibility Before Claiming', '伊莫首发奖励：领取前核对资格与历史记录', '伊莫首發獎勵：領取前核對資格與歷史紀錄'),
    subtitle: t('Separate the September reward display from a current account entitlement, then choose the appropriate official next step.', '区分9月奖励展示与当前账号资格，再选择对应的官方下一步。', '區分9月獎勵展示與目前帳號資格，再選擇對應的官方下一步。'),
    tag: t('Launch rewards', '首发奖励', '首發獎勵'),
    lead: t('Pre-registration is not the current route into the launched game. This page preserves the official website observation from September 26, 2026; it does not confirm that the same rewards remain claimable today.', '游戏已上线，预约不是当前进入游戏的途径。本页保留2026年9月26日的官网观察，不确认当时展示的奖励现在仍可领取。', '遊戲已上線，預約不是目前進入遊戲的途徑。本頁保留2026年9月26日的官網觀察，不確認當時展示的獎勵現在仍可領取。'),
    body: [
      { t: 'h', c: t('What did the September website observation establish?', '9月官网观察能确认什么？', '9月官網觀察能確認什麼？') },
      { t: 'p', c: t('The September 26 record lists four completed pre-registration milestones and launch benefits including a selected rare Shiny Aniimo, capture items, a limited Aniimo egg and four outfits. These are historical display categories, not a universal claim deadline or a guarantee that every account receives every item.', '9月26日记录列出四个已完成的预约里程碑，以及自选稀有 Shiny 伊莫、捕获道具、限定伊莫蛋和四套服装等首发福利。这些是历史展示类别，不是统一领取期限，也不保证每个账号都能获得每项道具。', '9月26日紀錄列出四個已完成的預約里程碑，以及自選稀有 Shiny 伊莫、捕獲道具、限定伊莫蛋和四套服裝等首發福利。這些是歷史展示類別，不是統一領取期限，也不保證每個帳號都能獲得每項道具。') },
      { t: 'h', c: t('Which next step matches my situation?', '哪种下一步符合我的情况？', '哪種下一步符合我的情況？') },
      { t: 'table', head: [t('Situation', '情况', '情況'), t('Check before acting', '操作前核对', '操作前核對')], rows: [
        [t('Not installed yet', '尚未安装', '尚未安裝'), t('Use the official download guide; a pre-registration counter is not an installer or a claim button.', '使用官方下载指南；预约计数不是安装包或领取按钮。', '使用官方下載指南；預約計數不是安裝包或領取按鈕。')],
        [t('Looking for a launch reward', '寻找首发奖励', '尋找首發獎勵'), t('Use the intended account, region and server. Check current event terms and mail for the exact reward, deadline and required opening steps.', '使用目标账号、地区和服务器，按当前活动条款与邮件核对具体奖励、截止时间及前置步骤。', '使用目標帳號、地區和伺服器，按目前活動條款與郵件核對具體獎勵、截止時間及前置步驟。')],
        [t('Reward missing despite matching terms', '符合条款但奖励未到账', '符合條款但獎勵未到帳'), t('Keep the campaign name and screenshots. Send account identifiers only through official private support; this site cannot verify entitlement or deliver rewards.', '保留活动名称与截图，仅通过官方私密支持渠道提供账号信息；本站不能核验资格或发放奖励。', '保留活動名稱與截圖，僅透過官方私密支援管道提供帳號資訊；本站不能核驗資格或發放獎勵。')],
      ] },
      { t: 'link', href: '/guide/how-to-download-aniimo', c: t('Choose a current official download route', '选择当前官方下载入口', '選擇目前官方下載入口') },
      { t: 'link', href: sourceById.get('aniimo-official-support-center')!.url, c: t('Open official support for a reward discrepancy', '奖励不符时联系官方支持', '獎勵不符時聯絡官方支援') },
      { t: 'quote', c: t('Editorial update November 2, 2026; the website reward observation remains dated September 26. No current universal eligibility, code, deadline or account delivery has been verified.', '编辑更新于2026年11月2日；官网奖励观察仍为9月26日。未核验当前统一资格、兑换码、截止时间或个别账号到账。', '編輯更新於2026年11月2日；官網獎勵觀察仍為9月26日。未核驗目前統一資格、兌換碼、截止時間或個別帳號到帳。') },
    ],
  };
  if (slug === 'aniimo-team-composition') {
    const entries = getAllAniimos();
    const covered = entries.filter(entry => entry.mobility.length > 0).length;
    return {
      title: t('Aniimo Team Composition: Compare Roles and Exploration Tasks', '伊莫队伍搭配：按定位与探索任务比较候选', '伊莫隊伍搭配：按定位與探索任務比較候選'),
      subtitle: t('Shortlist a documented ability, compare roles and elements, then check what the four-slot planning tool can establish.', '先找明确能力，再比较定位与元素，并核对四槽规划工具的结果范围。', '先找明確能力，再比較定位與元素，並核對四槽規劃工具的結果範圍。'),
      tag: t('Team planning', '队伍规划', '隊伍規劃'),
      lead: t(`Start with a task rather than the highest ATK. These counts use ${entries.length} Basic Form records from October 23; they describe the indexed roster, not a full current-game census or tested best team.`, `先确定任务，不只比较 ATK。以下统计来自10月23日的${entries.length}条基础形态记录，描述的是已索引范围，不是当前完整名单或实测最优队伍。`, `先確定任務，不只比較 ATK。以下統計來自10月23日的${entries.length}條基礎形態紀錄，描述的是已索引範圍，不是目前完整名單或實測最佳隊伍。`),
      body: [
        { t: 'h', c: t('1. Compare published roles without turning counts into rankings', '1. 比较已公布定位，不把人数当强度', '1. 比較已公布定位，不把人數當強度') },
        { t: 'table', head: [t('Role', '定位', '定位'), t('Indexed records', '已索引数', '已索引數')], rows: ['DPS', 'Break', 'Support', 'Regen', 'Heal'].map(role => [role, String(entries.filter(entry => entry.officialRole === role).length)]) },
        { t: 'p', c: t('A Support label alone does not prove healing; a Break label does not publish stagger speed or a capture bonus. Read the individual skills and their trigger conditions. The October 13 developer explanation warns against judging non-DPS damage by displayed ATK alone; it does not supply a complete current damage formula.', 'Support 标签不等于必定能治疗，Break 标签也没有给出破防速度或捕获加成。需要查看个体技能及触发条件。10月13日开发者说明提示不能仅按显示 ATK 判断非 DPS 伤害，但没有提供完整现行伤害公式。', 'Support 標籤不等於必定能治療，Break 標籤也沒有給出破防速度或捕獲加成。需要查看個體技能及觸發條件。10月13日開發者說明提示不能僅按顯示 ATK 判斷非 DPS 傷害，但沒有提供完整現行傷害公式。') },
        { t: 'link', href: '/guide/aniimo-roles-explained', c: t('Open examples for each role', '查看各定位的具体候选', '查看各定位的具體候選') },
        { t: 'h', c: t('2. Compare elements using the same snapshot', '2. 使用同一快照比较元素', '2. 使用同一快照比較元素') },
        { t: 'table', head: [t('Element', '元素', '元素'), t('Indexed records', '已索引数', '已索引數')], rows: ELEMENTS.map(element => [element, String(entries.filter(entry => entry.officialElements?.includes(element)).length)]) },
        { t: 'p', c: t('Dual-element records count in both element rows, but only once in the role table. Element labels are official; the separate matchup matrix is a community model with disputed cells. Its coverage score does not establish damage, survival or an optimal party.', '双元素记录在两个元素行中各计一次，定位表则每条只计一次。元素标签来自官方；独立克制表是含争议格子的社区模型，其覆盖率不能证明伤害、生存或最优队伍。', '雙元素紀錄在兩個元素行中各計一次，定位表則每條只計一次。元素標籤來自官方；獨立剋制表是含爭議格子的社群模型，其涵蓋率不能證明傷害、生存或最佳隊伍。') },
        { t: 'h', c: t('3. Choose a specific action before filling the party', '3. 填队伍前先明确具体操作', '3. 填隊伍前先明確具體操作') },
        { t: 'p', c: t(`${covered} of ${entries.length} indexed records list mobility across ${mobilityIndex.length} names. For flight, inspect Tromber's Take Off or Turbo's Cloudwalk; for underground interaction, inspect Budclaw's Tunnel. These are documented alternatives, not guarantees that every route is accessible. Missing mobility data means unknown.`, `${entries.length}条记录中${covered}条记载移动能力，共${mobilityIndex.length}个名称。飞行可核对 Tromber 的 Take Off 或 Turbo 的 Cloudwalk；地下交互可核对 Budclaw 的 Tunnel。这些是有记录的候选，不保证所有路线可通行；缺少移动能力数据表示未知。`, `${entries.length}條紀錄中${covered}條記載移動能力，共${mobilityIndex.length}個名稱。飛行可核對 Tromber 的 Take Off 或 Turbo 的 Cloudwalk；地下互動可核對 Budclaw 的 Tunnel。這些是有紀錄的候選，不保證所有路線可通行；缺少移動能力資料表示未知。`) },
        { t: 'link', href: '/tools/twine', c: t('Find the documented users of the needed ability', '反查所需能力的已记录使用者', '反查所需能力的已紀錄使用者') },
        { t: 'link', href: '/tools/team-builder', c: t('Compare four candidates in the party planner', '在四槽队伍工具比较候选', '在四槽隊伍工具比較候選') },
        { t: 'li', c: t('Apply an example to inspect four members, then replace one candidate and compare the changed ability and role coverage. Examples demonstrate the tool, not a tested combat recommendation or a universal party-size rule.', '可先载入四人示例，再替换一个候选，比较能力与定位覆盖变化。示例用于比较工具，不是战斗实测推荐，也不是所有模式的队伍人数规定。', '可先載入四人範例，再替換一個候選，比較能力與定位涵蓋變化。範例用於比較工具，不是戰鬥實測推薦，也不是所有模式的隊伍人數規定。') },
        { t: 'h', c: t('4. Keep capture planning separate from role labels', '4. 捕获规划与定位标签分开判断', '4. 捕獲規劃與定位標籤分開判斷') },
        { t: 'p', c: t('The October 27 disclosure separates ordinary field, ordinary battle and boss formulas. It does not list individual active-status coefficients. Do not assign a fixed BREAK multiplier from a role label; unknown required inputs must leave the estimate undetermined. Choose the encounter and compare one known change at a time.', '10月27日公示区分普通野外、普通战斗与 Boss 公式，没有列出各个活跃状态的具体系数。不能从 Break 定位推断固定 BREAK 倍率；必要输入未知时结果应保持未确定。先选遭遇类型，再逐项比较已知变化。', '10月27日公示區分普通野外、普通戰鬥與 Boss 公式，沒有列出各個活躍狀態的具體係數。不能從 Break 定位推斷固定 BREAK 倍率；必要輸入未知時結果應保持未確定。先選遭遇類型，再逐項比較已知變化。') },
        { t: 'link', href: '/guide/aniimo-catching-guide', c: t('Use the conditional capture examples', '查看有明确条件的捕获例子', '查看有明確條件的捕獲範例') },
        { t: 'quote', c: t('Editorial update November 2, 2026; roster snapshot October 23 and capture disclosure October 27. No combat rotation, best build or capture team was playtested.', '编辑更新于2026年11月2日；名单快照为10月23日，捕获公示为10月27日。未实测战斗循环、最优配装或捕获队伍。', '編輯更新於2026年11月2日；名單快照為10月23日，捕獲公示為10月27日。未實測戰鬥循環、最佳配裝或捕獲隊伍。') },
      ],
    };
  }
  if (slug === 'aniimo-choose-by-mobility-role') return {
    title: t('Choose Aniimo by Mobility Ability and Combat Role', '按移动能力与战斗定位选择伊莫', '按移動能力與戰鬥定位選擇伊莫'),
    subtitle: t('Find actual users of an ability instead of assigning one family member’s ability to the whole family.', '核对能力的实际使用者，避免把个体能力套用到整个家族。', '核對能力的實際使用者，避免把個體能力套用到整個家族。'),
    tag: t('Selection guide', '候选选择', '候選選擇'),
    lead: t('Start with a named action, then inspect a specific creature. The examples below use the October 23 Basic Form index and show up to three documented users per ability in official-number order.', '先明确具名操作，再查看具体个体。下表使用10月23日基础形态索引，按官方编号为每项能力展示最多3名已记载使用者。', '先明確具名操作，再查看具體個體。下表使用10月23日基礎形態索引，按官方編號為每項能力展示最多3名已記載使用者。'),
    body: [
      { t: 'h', c: t('1. Choose an actual ability user', '1. 选择确实记载能力的个体', '1. 選擇確實記載能力的個體') },
      { t: 'table', head: [t('Ability', '能力', '能力'), t('Documented examples', '已记载的个体示例', '已記載的個體範例')], rows: ['Hustle', 'Take Off', 'Cloudwalk', 'Cloak', 'Tunnel', 'Glow'].flatMap(name => {
        const group = mobilityIndex.find(group => group.name === name);
        return group ? [[name, group.members.slice(0, 3).map(member => `#${member.officialNumber} ${member.enName}`).join(' / ')]] : [];
      }) },
      { t: 'p', c: t('A family label is not an ability shared by every stage. Nimbi lists Puff Up, while Turbo lists Cloudwalk. Take Off is documented for Tromber, Cornet and Fragrancier, not for basic Chirpi in this snapshot. A blank Chirpi mobility field remains unknown rather than proving absence in the live game.', '家族标签不代表每个阶段共享能力。Nimbi 记载 Puff Up，Turbo 才记载 Cloudwalk。此快照中 Take Off 对应 Tromber、Cornet 和 Fragrancier，不是基础 Chirpi；Chirpi 移动字段为空表示未知，不能证明当前游戏没有能力。', '家族標籤不代表每個階段共享能力。Nimbi 記載 Puff Up，Turbo 才記載 Cloudwalk。此快照中 Take Off 對應 Tromber、Cornet 和 Fragrancier，不是基礎 Chirpi；Chirpi 移動欄位為空表示未知，不能證明目前遊戲沒有能力。') },
      { t: 'link', href: '/dex/008', c: t('Inspect Tromber and Take Off', '查看 Tromber 的 Take Off', '查看 Tromber 的 Take Off') },
      { t: 'link', href: '/dex/019', c: t('Inspect Turbo and Cloudwalk', '查看 Turbo 的 Cloudwalk', '查看 Turbo 的 Cloudwalk') },
      { t: 'link', href: '/tools/twine', c: t('Find all indexed users of another ability', '反查其他能力的全部已索引使用者', '反查其他能力的全部已索引使用者') },
      { t: 'h', c: t('2. Compare combat function separately', '2. 单独比较战斗功能', '2. 單獨比較戰鬥功能') },
      { t: 'p', c: t('A published DPS, Break, Support, Regen or Heal label narrows the task, not the strength. Read each skill’s target, cost and trigger before comparing candidates. ATK, a family name or the number of skills alone does not establish damage, a best build or a verified rotation.', 'DPS、Break、Support、Regen、Heal 定位用于缩小任务范围，不是强度结论。比较候选前查看每项技能的目标、消耗与触发条件；仅凭 ATK、家族名或技能数量不能得出伤害、最优配装或实测循环。', 'DPS、Break、Support、Regen、Heal 定位用於縮小任務範圍，不是強度結論。比較候選前查看每項技能的目標、消耗與觸發條件；僅憑 ATK、家族名或技能數量不能得出傷害、最佳配裝或實測循環。') },
      { t: 'link', href: '/guide/aniimo-team-composition', c: t('Compare current indexed role counts and party tasks', '比较当前已索引定位统计与组队任务', '比較目前已索引定位統計與組隊任務') },
      { t: 'quote', c: t('Edited November 2, 2026 using the October 23 snapshot. No terrain route or combat performance was playtested.', '2026年11月2日编辑，依据10月23日快照；未实测地形路线或战斗表现。', '2026年11月2日編輯，依據10月23日快照；未實測地形路線或戰鬥表現。') },
    ],
  };
  if (slug === 'aniimo-multiplayer') return {
    title: t('Aniimo Multiplayer: Choose Co-op, Fair PVP or PVE / Chaos', '伊莫多人玩法：合作、公平 PVP 与 PVE／混沌怎么选', '伊莫多人玩法：合作、公平 PVP 與 PVE／混沌怎麼選'),
    subtitle: t('Compare the announced mode gates and preparation rules, then open the relevant current guide.', '比较公告中的玩法门槛与准备规则，再进入对应现行攻略。', '比較公告中的玩法門檻與準備規則，再進入對應現行攻略。'),
    tag: t('Multiplayer', '多人玩法', '多人玩法'),
    lead: t('Choose the activity before forming a party. The October 29 announcement separates fair PVP from PVE / Chaos and lets each Holo-Battle path support solo, team or matching. A general co-op storefront label does not establish every mode’s party size or platform pairing.', '先选玩法，再组队。10月29日公告区分公平 PVP 与 PVE／混沌，并让 Holo-Battle 各路支持单人、组队或匹配。商店笼统的合作标签不能说明每种模式的人数或平台配对。', '先選玩法，再組隊。10月29日公告區分公平 PVP 與 PVE／混沌，並讓 Holo-Battle 各路支援單人、組隊或配對。商店籠統的合作標籤不能說明每種模式的人數或平台配對。'),
    body: [
      { t: 'h', c: t('Which activity matches my goal?', '哪种玩法符合我的目标？', '哪種玩法符合我的目標？') },
      { t: 'table', head: [t('Goal / mode', '目标／模式', '目標／模式'), t('Entry check', '入口检查', '入口檢查'), t('Preparation decision', '准备判断', '準備判斷')], rows: [
        ['Egg Heist · fair PVP', t('Level 50 + Rising Egg Scout; announced 18:00–24:00 daily, verify your server timer.', '50级＋Rising Egg Scout；公告每日18:00–24:00，核对所在服计时。', '50級＋Rising Egg Scout；公告每日18:00–24:00，核對所在服計時。'), t('Three competing teams, adjusted deployed stats, no carried items or configured equipment loadout. Final Giga-Egg Twine ownership decides the win.', '三队竞争，出战数值调整，不携带物品或配置装备；最后 Giga-Egg Twine 归属决定胜利。', '三隊競爭，出戰數值調整，不攜帶物品或配置裝備；最後 Giga-Egg Twine 歸屬決定勝利。')],
        ['Egg Heist · PVE / Chaos', t('Check the current difficulty. September Chaos rules list Elite Egg Seeker Tier IV + Chaos Ticket.', '先看当前难度；9月混沌规则列 Elite Egg Seeker Tier IV＋Chaos Ticket。', '先看目前難度；9月混沌規則列 Elite Egg Seeker Tier IV＋Chaos Ticket。'), t('Use that difficulty’s combat and recovery rules; do not apply fair PVP stat and equipment restrictions to it.', '按对应难度准备战斗与恢复，不套用公平 PVP 的数值和装备限制。', '按對應難度準備戰鬥與恢復，不套用公平 PVP 的數值和裝備限制。')],
        ['Holo-Battle Interlink', t('Trailblazer I; Thursday 04:00–Monday 03:59, check the server interface.', 'Trailblazer I；周四04:00至周一03:59，以所在服界面核对。', 'Trailblazer I；週四04:00至週一03:59，以所在服介面核對。'), t('Independent left/middle/right paths with solo, team or matching. Inspect the selected path and manually claim star rewards.', '左中右路独立，各可单人、组队或匹配；核对所选路线，手动领星级奖励。', '左中右路獨立，各可單人、組隊或配對；核對所選路線，手動領星級獎勵。')],
      ] },
      { t: 'link', href: '/guide/aniimo-egg-heist', c: t('Compare Egg Heist rules and post-update egg delivery', '比较 Egg Heist 规则与更新后的蛋发放', '比較 Egg Heist 規則與更新後的蛋發放') },
      { t: 'link', href: '/guide/aniimo-holo-battle-interlink', c: t('Check the weekly path and reward workflow', '核对周常路线与领奖流程', '核對週常路線與領獎流程') },
      { t: 'h', c: t('Can my friends join from another platform?', '朋友使用其他平台能一起玩吗？', '朋友使用其他平台能一起玩嗎？') },
      { t: 'p', c: t('Steam lists cross-platform multiplayer, but these sources do not provide every supported platform pairing or a complete save/purchase transfer policy. Confirm activity, region, server, client version and the actual invitation screen with your friends. A four-slot planning tool is not proof of four-player support for every activity.', 'Steam 列出跨平台多人，但这些来源没有给出全部平台配对或完整存档／付费内容转移规则。与朋友核对玩法、地区、服务器、客户端版本和实际邀请界面。四槽规划工具不能证明所有活动都支持四人。', 'Steam 列出跨平台多人，但這些來源沒有給出全部平台配對或完整存檔／付費內容轉移規則。與朋友核對玩法、地區、伺服器、用戶端版本和實際邀請介面。四槽規劃工具不能證明所有活動都支援四人。') },
      { t: 'link', href: '/guide/aniimo-crossplay-cross-save', c: t('Check platform pairing and account-transfer boundaries', '查看平台配对与账号转移的证据范围', '查看平台配對與帳號轉移的證據範圍') },
      { t: 'quote', c: t('Reviewed November 2 using the October 29 update announcement and dated September mode rules. No queue times, live matchmaking availability or best team is measured here.', '11月2日按10月29日更新公告与带日期的9月模式规则整理。未测量排队耗时、实时匹配开放或最优队伍。', '11月2日按10月29日更新公告與帶日期的9月模式規則整理。未測量排隊耗時、即時配對開放或最佳隊伍。') },
    ],
  };
  if (slug === 'aniimo-twine-explained') return {
    title: t('Aniimo Twine: Choose an Ability and Find Its Users', '伊莫 Twine：按探索能力寻找可用伊莫', '伊莫 Twine：按探索能力尋找可用伊莫'),
    subtitle: t('Turn an exploration need into a shortlist using the published mobility records, then inspect the individual ability.', '从探索需求出发，用已公布的移动能力对应表筛选，再核对个体能力说明。', '從探索需求出發，用已公布的移動能力對應表篩選，再核對個體能力說明。'),
    tag: 'Twine',
    lead: t('Twine lets a Pathfinder become a collected Aniimo and use its abilities. To find a candidate for a route, start with the required action, not the creature’s element or combat skill name. The October 23 snapshot already contains official ability-to-creature mappings within its 86 Basic Form records; it is not a complete current-game list.', 'Twine 让玩家变为已收集伊莫并使用其能力。为路线选候选时，先明确需要的操作，不凭元素或战斗技能名称判断。10月23日的86个基础形态快照内已有官方能力对应关系，但并非当前游戏完整名单。', 'Twine 讓玩家變為已收集伊莫並使用其能力。為路線選候選時，先明確需要的操作，不憑元素或戰鬥技能名稱判斷。10月23日的86個基礎形態快照內已有官方能力對應關係，但並非目前遊戲完整名單。'),
    body: [
      { t: 'h', c: t('1. Check a published ability before choosing', '1. 先看已公布能力，再选候选', '1. 先看已公布能力，再選候選') },
      { t: 'p', c: t('The examples below select four named abilities to compare different exploration actions; they are not a strength ranking or an exhaustive category list. Members and counts come from the same index as the ability directory and Twine lookup.', '下表选取四项具名能力，便于比较不同探索操作，不是强度排名或完整分类。成员和数量与能力目录、Twine 反查共用同一索引。', '下表選取四項具名能力，便於比較不同探索操作，不是強度排名或完整分類。成員和數量與能力目錄、Twine 反查共用同一索引。') },
      { t: 'table', head: [t('Ability', '能力', '能力'), t('Indexed members', '已索引成员数', '已索引成員數'), t('Examples: first three by official number', '示例：按官方编号取前3个', '範例：按官方編號取前3個')], rows: ['Hustle', 'Take Off', 'Cloudwalk', 'Floaty Bubble'].flatMap(name => {
        const group = mobilityIndex.find(group => group.name === name);
        return group ? [[name, String(group.members.length), group.members.slice(0, 3).map(member => member.enName).join(' / ')]] : [];
      }) },
      { t: 'link', href: '/tools/twine', c: t('Choose abilities and view every matching indexed Aniimo', '选择能力，查看所有匹配的已索引伊莫', '選擇能力，查看所有符合的已索引伊莫') },
      { t: 'h', c: t('2. Use the lookup without confusing any-match and all-match', '2. 区分匹配任一能力与同时满足', '2. 區分符合任一能力與同時滿足') },
      { t: 'li', c: t('Select one named ability. Open a matching creature to read the mobility description and the published habitats before planning capture.', '先选一项具名能力，打开匹配个体，阅读移动能力说明与已公布栖息地后再规划捕获。', '先選一項具名能力，開啟符合個體，閱讀移動能力說明與已公布棲息地後再規劃捕獲。') },
      { t: 'li', c: t('Selecting several abilities returns creatures matching any selected ability. It does not promise one creature has them all. For a multi-action route, inspect each candidate or compare a party in the team tool.', '多选返回具备任意一项所选能力的伊莫，不代表同一个体同时具备全部能力。多操作路线应逐个核对，或在组队工具比较全队覆盖。', '多選返回具備任意一項所選能力的伊莫，不代表同一個體同時具備全部能力。多操作路線應逐個核對，或在組隊工具比較全隊涵蓋範圍。') },
      { t: 'li', c: t('An empty selection resets the lookup to all indexed entries; it is not a filter for missing mobility data. A missing field does not prove the ability is absent in the live game.', '不选能力会重置为所有已索引条目，不是筛选缺少移动能力的伊莫。字段为空不证明当前游戏没有该能力。', '不選能力會重設為所有已索引條目，不是篩選缺少移動能力的伊莫。欄位為空不證明目前遊戲沒有該能力。') },
      { t: 'link', href: '/tools/team-builder', c: t('Compare which party members cover different actions', '比较不同队员分别覆盖哪些操作', '比較不同隊員分別涵蓋哪些操作') },
      { t: 'h', c: t('3. Check the action, not a similar-sounding combat skill', '3. 核对操作，不只看相似技能名', '3. 核對操作，不只看相似技能名') },
      { t: 'p', c: t('Hustle spends stamina for movement speed; it does not establish flight or swimming. Celestis has a combat skill named Star Glide, but its imported mobility field is empty: that name alone does not prove exploration gliding. Neither a habitat name nor a mobility label supplies coordinates, unlock requirements or guaranteed terrain access.', 'Hustle 是消耗体力提高移速，不能据此确认飞行或游泳。Celestis 虽有战斗技能 Star Glide，但导入的移动能力为空，名称本身不能证明探索滑翔。栖息地或移动能力标签也不能给出坐标、解锁条件或保证通过某种地形。', 'Hustle 是消耗體力提高移速，不能據此確認飛行或游泳。Celestis 雖有戰鬥技能 Star Glide，但匯入的移動能力為空，名稱本身不能證明探索滑翔。棲息地或移動能力標籤也不能給出座標、解鎖條件或保證通過某種地形。') },
      { t: 'link', href: '/dex/005', c: t('Inspect Celestis: combat skills versus mobility evidence', '查看 Celestis：区分战斗技能与移动证据', '查看 Celestis：區分戰鬥技能與移動證據') },
      { t: 'link', href: '/abilities', c: t('Read the ability directory and its snapshot scope', '查看能力目录及快照范围', '查看能力目錄及快照範圍') },
      { t: 'quote', c: t('Editorial update: November 2, 2026. Mapping evidence remains the October 23 Wiki snapshot. No traversal route or unlock sequence was playtested here.', '编辑更新：2026年11月2日。对应关系仍依据10月23日 Wiki 快照，未实测地形路线或解锁顺序。', '編輯更新：2026年11月2日。對應關係仍依據10月23日 Wiki 快照，未實測地形路線或解鎖順序。') },
    ],
  };
  if (slug === 'official-aniimo-dex-status') return {
    title: t('AniimoDex Coverage: Available Answers and Data Limits', 'AniimoDex 资料覆盖：可用答案与数据边界', 'AniimoDex 資料涵蓋：可用答案與資料邊界'),
    subtitle: t('Find the right database, tool or guide, and distinguish snapshot values from current announcements and unknowns.', '找到对应图鉴、工具或攻略，区分快照数值、当前公告与尚未确认的信息。', '找到對應圖鑑、工具或攻略，區分快照數值、目前公告與尚未確認的資訊。'),
    tag: t('Data coverage', '资料覆盖', '資料涵蓋'),
    lead: t('Choose the question below. The database has 91 Basic Form records: 86 checked October 23 and Royalby, Pouchwisp, Jeburst and Glameep checked November 8, plus Jaguaraun checked November 9. Glameep retains its earlier URL. Eleven unmatched August records remain historical and are excluded from current comparisons. This is not a complete S1 Part 2 roster.', '按下表选择问题。图鉴有91条基础形态：10月23日核验的86条，以及11月8日核验的 Royalby、Pouchwisp、Jeburst、Glameep，以及11月9日核验的 Jaguaraun。Glameep 保留原网址。11条8月未匹配记录仍为历史资料，不参与当前比较；这不是 S1 后半段完整名单。', '按下表選擇問題。圖鑑有91條基礎形態：10月23日核驗的86條，以及11月8日核驗的 Royalby、Pouchwisp、Jeburst、Glameep，以及11月9日核驗的 Jaguaraun。Glameep 保留原網址。11條8月未匹配記錄仍為歷史資料，不參與目前比較；這不是 S1 後半段完整名單。'),
    body: [
      { t: 'h', c: t('1. What can I do now?', '1. 现在可以完成什么？', '1. 現在可以完成什麼？') },
      { t: 'table', head: [t('Question', '问题', '問題'), t('Available answer', '可用答案', '可用答案'), t('Boundary', '边界', '邊界')], rows: [
        [t('Compare creatures', '比较伊莫', '比較伊莫'), t('Six attributes, skill Type/Cost/Power and roles on 91 records; families only where resolved.', '91条记录的六项属性、技能 Type／Cost／Power 与定位；家族仅展示已解析部分。', '91條記錄的六項屬性、技能 Type／Cost／Power 與定位；家族僅展示已解析部分。'), t('Basic Form snapshot, not level-adjusted stats or a complete Part 2 roster.', '基础形态快照，不是等级换算数值或完整后半段名单。', '基礎形態快照，不是等級換算數值或完整後半段名單。')],
        [t('Find an exploration ability', '寻找探索能力', '尋找探索能力'), t('Ability-to-creature lookup, habitat groups and party mobility coverage.', '能力对应反查、栖息地分组与全队移动能力覆盖。', '能力對應反查、棲息地分組與全隊移動能力涵蓋。'), t('Missing fields are unknown; no guaranteed spawn coordinates.', '字段缺失表示未知，不保证出现坐标。', '欄位缺失表示未知，不保證出現座標。')],
        [t('Estimate capture', '估算捕获', '估算捕獲'), t('October 27 disclosure: field, battle and boss models with explicit assumptions.', '10月27日公示：野外、战斗与 Boss 的条件模型。', '10月27日公示：野外、戰鬥與 Boss 的條件模型。'), t('Unknown required inputs block a numeric result; not a measured species success rate.', '必要输入未知时不输出数字，不是物种实测成功率。', '必要輸入未知時不輸出數字，不是物種實測成功率。')],
        [t('Plan Part 2 activities', '规划后半段活动', '規劃後半段活動'), t('Server-specific rotation calendar, growth gates and mode/item comparisons.', '分服轮换表、成长门槛与模式／道具对照。', '分服輪換表、成長門檻與模式／道具對照。'), t('Announcement evidence, not live server monitoring or gameplay tests.', '依据公告，不是实时服务器监控或玩法实测。', '依據公告，不是即時伺服器監控或玩法實測。')],
      ] },
      { t: 'link', href: '/dex', c: t('Search and compare the indexed Basic Form records', '检索与比较已索引基础形态', '檢索與比較已索引基礎形態') },
      { t: 'link', href: '/tools/twine', c: t('Find a creature by the ability you need', '按需要的能力寻找候选', '按需要的能力尋找候選') },
      { t: 'link', href: '/guide/aniimo-catching-guide', c: t('Compare capture assumptions with worked examples', '通过具体例子比较捕获条件', '透過具體範例比較捕獲條件') },
      { t: 'link', href: '/guide/aniimo-prismana-event-tracker', c: t('Choose the correct server calendar', '选择对应服务器排期', '選擇對應伺服器排期') },
      { t: 'h', c: t('2. What remains outside this coverage?', '2. 哪些仍不在覆盖范围内？', '2. 哪些仍不在涵蓋範圍內？') },
      { t: 'p', c: t('Part 2 additions and alternate-form attributes are not fully indexed. Six unresolved evolution trees are withheld rather than guessed. A Wiki habitat is not a verified encounter route; form names do not establish stat changes, breeding recipes or an optimal team. The community element chart keeps disputed cells unknown and excludes affected numeric comparisons.', '后半段新增伊莫与其他形态数值尚未完整索引；6棵未完全匹配的进化树不猜测发布。Wiki 栖息地不是已实测遭遇路线；形态名称不能证明数值变化、繁育配方或最优队伍。社区元素表对有争议格子保留未知，并排除受影响的数值比较。', '後半段新增伊莫與其他形態數值尚未完整索引；6棵未完全符合的進化樹不猜測發布。Wiki 棲息地不是已實測遭遇路線；形態名稱不能證明數值變化、繁育配方或最佳隊伍。社群元素表對有爭議格子保留未知，並排除受影響的數值比較。') },
      { t: 'link', href: '/guide/aniimo-version-1-1-update', c: t('Use the sourced growth checklist without assuming the whole Dex is updated', '使用有依据的成长清单，并区分图鉴覆盖', '使用有依據的成長清單，並區分圖鑑涵蓋') },
      { t: 'h', c: t('3. How do I check a claim or report a correction?', '3. 如何核对结论或反馈更正？', '3. 如何核對結論或回報更正？') },
      { t: 'p', c: t('Read the individual page’s source dates and named scope. Editorial dates mark material page changes; they do not relabel an older snapshot as today’s data. Corrections should include the affected page, the disputed claim and a relevant official notice or reproducible record. A tested recommendation requires its game version and observations, not a source badge alone.', '查看具体页面的来源日期和范围。编辑日期表示页面有实质修改，不会把旧快照改称当天数据。反馈请附页面、争议结论与对应官方公告或可复现记录。实测推荐需要版本与观察记录，不能只靠来源标记。', '查看具體頁面的來源日期和範圍。編輯日期表示頁面有實質修改，不會把舊快照改稱當天資料。回報請附頁面、爭議結論與對應官方公告或可重現紀錄。實測推薦需要版本與觀察紀錄，不能只靠來源標記。') },
      { t: 'link', href: '/guide/how-we-verify', c: t('Check evidence labels and the verification method', '查看证据标注与核验方法', '查看證據標註與核驗方法') },
      { t: 'link', href: '/contact', c: t('Send a factual correction', '反馈事实更正', '回報事實更正') },
      { t: 'quote', c: t('Coverage guide updated November 2, 2026. Use the linked pages for available answers and check each source date; current-game species and form coverage remains incomplete.', '资料覆盖页更新于2026年11月2日。请通过对应链接查找答案并核对来源日期；当前游戏物种与形态资料仍未完整覆盖。', '資料涵蓋頁更新於2026年11月2日。請透過對應連結查找答案並核對來源日期；目前遊戲物種與形態資料仍未完整涵蓋。') },
    ],
  };
  if (slug === 'aniimo-rv-homeland-guide') return {
    title: t('Aniimo Home: Magical Wonder Night Entry & Season Changes', '伊莫家园：Magical Wonder Night 入口与换季清单', '伊莫家園：Magical Wonder Night 入口與換季清單'),
    subtitle: t('Check RV level, the tutorial quest, old-currency conversion and blueprint changes before planting or exchanging.', '种植或兑换前，核对房车等级、教程任务、旧货币转换与蓝图变化。', '種植或兌換前，核對房車等級、教學任務、舊貨幣轉換與藍圖變化。'),
    tag: t('Home season', '家园换季', '家園換季'),
    lead: t('The October 29 update replaces Harvest Moon Festival with Magical Wonder Night. Start by checking RV level 10 and Act Seven: Festivals of Astra. Do not plan current purchases around the old October 20–21 Harvest Gathering schedule or assume old seeds still plant normally.', '10月29日更新将丰收季切换为 Magical Wonder Night。先核对房车10级与 Act Seven: Festivals of Astra；当前兑换不应沿用10月20–21日丰收聚会排期，也不能假设旧种子仍可正常种植。', '10月29日更新將豐收季切換為 Magical Wonder Night。先核對房車10級與 Act Seven: Festivals of Astra；目前兌換不應沿用10月20–21日豐收聚會排期，也不能假設舊種子仍可正常種植。'),
    body: [
      { t: 'h', c: t('Start here: entry missing, activity locked or old items gone?', '先定位：没有入口、活动锁定，还是旧物品不见了？', '先定位：沒有入口、活動鎖定，還是舊物品不見了？') },
      { t: 'link', href: sourceById.get('aniimo-s1-part-two-2026-10-27')!.url, c: t('Checklist updated November 3: October 29 Home season announcement', '11月3日更新检查流程：查看10月29日家园换季公告', '11月3日更新檢查流程：查看10月29日家園換季公告') },
      { t: 'p', c: t('Follow the row matching your symptom. This is an editorial checklist derived from the announced conditions, not a tested sequence of client buttons. A missing season entry and a later-stage lock need different checks.', '按当前症状选择一行。本表依据公告条件整理，不是已实测的客户端按钮操作顺序；赛季没有入口与后续阶段未开放，要检查的条件不同。', '按目前症狀選擇一列。本表依據公告條件整理，不是已實測的客戶端按鈕操作順序；賽季沒有入口與後續階段未開放，要檢查的條件不同。') },
      { t: 'table', head: [t('What you see', '当前情况', '目前情況'), t('Check in this order', '依次核对', '依次核對'), t('What to do next', '下一步', '下一步')], rows: [
        [t('No Magical Wonder Night entry', '没有 Magical Wonder Night 入口', '沒有 Magical Wonder Night 入口'), t('RV level 10 → completed Act Seven: Festivals of Astra → current server season panel.', '房车10级 → 已完成 Act Seven: Festivals of Astra → 所在服赛季面板。', '房車10級 → 已完成 Act Seven: Festivals of Astra → 所在服賽季面板。'), t('If a prerequisite is missing, complete it. If both are met, record the panel and client version for support; do not buy furniture to unlock entry.', '缺哪项先补哪项；两项都满足仍无入口，记录面板与版本反馈，不靠买家具解锁。', '缺哪項先補哪項；兩項都滿足仍無入口，記錄面板與版本回報，不靠買家具解鎖。')],
        [t('Season opens, but an activity is locked', '赛季能进，但某项活动锁定', '賽季能進，但某項活動鎖定'), t('Exact activity name → its stage requirement → server countdown.', '活动准确名称 → 对应阶段条件 → 所在服倒计时。', '活動準確名稱 → 對應階段條件 → 所在服倒數計時。'), t('Wait for the displayed stage if it is upcoming. Do not assume RV level 20 opens every activity.', '若显示尚未开放，按阶段等待；不能认定房车20级就能开全部活动。', '若顯示尚未開放，按階段等待；不能認定房車20級就能開全部活動。')],
        [t('Old seeds or currency disappeared', '旧种子或货币不见了', '舊種子或貨幣不見了'), t('Exact old item → destination in the conversion table below → current inventory.', '旧物品准确名称 → 下方转换表目标 → 当前库存。', '舊物品準確名稱 → 下方轉換表目標 → 目前庫存。'), t('Check Home Coin or Wonder Sugar Crystal as appropriate before reporting a loss. A conversion announcement alone cannot prove the amount credited to your account.', '先按对应关系查 Home Coin 或 Wonder Sugar Crystal，再反馈丢失；转换公告本身不能证明个别账号到账数量。', '先按對應關係查 Home Coin 或 Wonder Sugar Crystal，再回報遺失；轉換公告本身不能證明個別帳號到帳數量。')],
        [t('Harvest Moon Set is absent from the shop', '商店没有 Harvest Moon Set', '商店沒有 Harvest Moon Set'), t('Seasonal removal → future return announced without a date.', '换季移除 → 公告未来回归，但无日期。', '換季移除 → 公告未來回歸，但無日期。'), t('Check current stock; an old purchase guide cannot establish present availability.', '按当前库存判断，旧购买攻略不能证明现在仍可兑换。', '按目前庫存判斷，舊購買攻略不能證明現在仍可兌換。')],
      ] },
      { t: 'h', c: t('1. Confirm access and your server clock', '1. 核对入口与服务器时间', '1. 核對入口與伺服器時間') },
      { t: 'p', c: t('The announced requirement is RV level 10 plus completion of Act Seven: Festivals of Astra. The season runs after the update to December 10 at 03:59, using Europe UTC+0, Americas UTC-4 and APAC UTC+8 respectively. Check the current in-game panel for amendments; an unlocked season does not mean every later-stage event is already open.', '公告要求房车10级，并完成 Act Seven: Festivals of Astra。赛季从更新后至12月10日03:59，分别使用欧洲 UTC+0、美洲 UTC-4、亚太 UTC+8。变更以所在服当前面板为准；赛季已开不代表所有阶段活动同时开放。', '公告要求房車10級，並完成 Act Seven: Festivals of Astra。賽季從更新後至12月10日03:59，分別使用歐洲 UTC+0、美洲 UTC-4、亞太 UTC+8。變更以所在服目前面板為準；賽季已開不代表所有階段活動同時開放。') },
      { t: 'h', c: t('2. Identify what changed before spending', '2. 消耗前区分换季变化', '2. 消耗前區分換季變化') },
      { t: 'table', head: [t('Item / goal', '物品／目标', '物品／目標'), t('Announced change', '公告变化', '公告變化'), t('Practical check', '实际核对', '實際核對')], rows: [
        ['Moonbeam Wheat / Moondew Radish Seeds / Waxing Moon Pepper Seeds', t('Converted to Home Coin after the season change.', '换季后转换为 Home Coin。', '換季後轉換為 Home Coin。'), t('Check converted inventory before treating a missing old seed as lost progress. No conversion ratio is established here.', '先查转换后库存，再判断旧种子是否丢失；本页未确认换算比例。', '先查轉換後庫存，再判斷舊種子是否遺失；本頁未確認換算比例。')],
        ['Waxing Moondew', t('Converted to Wonder Sugar Crystal.', '转换为 Wonder Sugar Crystal。', '轉換為 Wonder Sugar Crystal。'), t('Compare the new exchange material, not the old crop currency.', '核对新兑换材料，不沿用旧作物货币。', '核對新兌換材料，不沿用舊作物貨幣。')],
        ['Harvest Moon Set', t('Removed from the season shop; a future return is announced without a date.', '从赛季商店移除；公告会在未来回归，未给日期。', '從賽季商店移除；公告會在未來回歸，未給日期。'), t('Do not describe it as permanently exclusive or currently purchasable.', '不能称为永久绝版或当前可买。', '不能稱為永久絕版或目前可買。')],
        ['Magic Pumpkin / Memory Lanternfruit', t('New magical crops with mutated forms for the Index.', '新魔法作物，可发现变异形态点亮索引。', '新魔法作物，可發現變異形態點亮索引。'), t('Check current crop tasks; old mutation bonuses are not automatically carried over.', '对照当前作物任务，不能默认旧变异增益延续。', '對照目前作物任務，不能預設舊變異增益延續。')],
        ['Wonder Dailies / Nighttime Gathering / Pumpkin God’s Thank-You Gift', t('Open gradually with season stages.', '按赛季阶段逐步开放。', '按賽季階段逐步開放。'), t('Read the stage lock and timer before treating an unavailable entry as a bug.', '先看阶段锁与倒计时，再判断无入口是否故障。', '先看階段鎖與倒數計時，再判斷無入口是否故障。')],
      ] },
      { t: 'h', c: t('3. Separate building changes from season requirements', '3. 区分建造更新与赛季门槛', '3. 區分建造更新與賽季門檻') },
      { t: 'p', c: t('November 5 v1.1.3880756.0 now permits level 1 facilities to use Season Recipes and lists fixes for some Home furniture displays. Facility level is not RV level: this change does not replace RV level 10 plus Act Seven season entry. Before upgrading a facility solely for a recipe, check the current recipe, required inputs and displayed output; the patch publishes no production rate or optimal layout. A display fix does not prove missing furniture was reissued.', '11月5日 v1.1.3880756.0 已允许1级设施使用 Season Recipes，并列出部分家园家具显示修复。设施等级不是房车等级，这项调整没有替代房车10级加 Act Seven 的赛季入口条件。为配方单独升级设施前，先看当前配方、所需投入与界面产出；补丁没有公布生产效率或最优布局。显示修复也不能证明缺失家具已补发。', '11月5日 v1.1.3880756.0 已允許1級設施使用 Season Recipes，並列出部分家園家具顯示修正。設施等級不是房車等級，這項調整沒有替代房車10級加 Act Seven 的賽季入口條件。為配方單獨升級設施前，先看目前配方、所需投入與介面產出；補丁沒有公布生產效率或最佳佈局。顯示修正也不能證明缺失家具已補發。') },
      { t: 'link', href: sourceById.get('aniimo-patch-1-1-3880756-2026-11-05')!.url, c: t('November 5 source: level 1 facilities and furniture display fixes', '11月5日来源：1级设施与家具显示修复', '11月5日來源：1級設施與家具顯示修正') },
      { t: 'p', c: t('The update adds RV levels, a three-story structure, full skin replacement, weather, full Home blueprint application and blueprint-code sharing. This does not publish every roof limit, material quantity or a best production layout. Inspect a blueprint’s required furniture and the displayed cost before acquiring items. Glow Scooter is a separate RV level 20 reward, used from Social Panel - Vehicles; it is not the level 10 season-entry requirement.', '更新增加房车等级、三层结构、整车换肤、天气、完整家园蓝图应用与蓝图码分享，但没有给出全部屋顶限制、材料数量或最优生产布局。使用蓝图前核对所需家具与界面费用。Glow Scooter 是单独的房车20级奖励，在 Social Panel - Vehicles 使用，不是10级赛季入口条件。', '更新增加房車等級、三層結構、整車換膚、天氣、完整家園藍圖套用與藍圖碼分享，但沒有給出全部屋頂限制、材料數量或最佳生產佈局。使用藍圖前核對所需家具與介面費用。Glow Scooter 是單獨的房車20級獎勵，在 Social Panel - Vehicles 使用，不是10級賽季入口條件。') },
      { t: 'h', c: t('4. Missing items or an unavailable activity?', '4. 物品缺失或活动没入口？', '4. 物品缺失或活動沒入口？') },
      { t: 'p', c: t('Record client version, server, RV level, completed tutorial and the exact missing item or stage. Compare the conversion table and stage timer first. For missing models, leave and re-enter Home once, then capture the layout and report the symptom; do not delete buildings or buy replacements just to test a guess.', '记录版本、服务器、房车等级、教程完成情况与准确缺失物品或阶段。先对照转换表和阶段计时。模型缺失可离开再进入家园一次，仍异常则截图布局并反馈；不要为试错删除建筑或重复购买。', '記錄版本、伺服器、房車等級、教學完成情況與準確缺失物品或階段。先對照轉換表和階段計時。模型缺失可離開再進入家園一次，仍異常則截圖佈局並回報；不要為試錯刪除建築或重複購買。') },
      { t: 'link', href: '/guide/aniimo-launch-checklist-known-issues', c: t('Match a symptom to a dated fix or official support', '按症状查看带日期修复与官方支持', '按症狀查看帶日期修正與官方支援') },
      { t: 'link', href: '/guide/aniimo-harvest-gathering-farm-guide', c: t('Historical Harvest Gathering schedule and its limits', '历史丰收聚会排期与适用边界', '歷史豐收聚會排期與適用邊界') },
      { t: 'quote', c: t('Reviewed November 2, 2026 against the October 27 announcement for October 29. October 15 v1.0.3732728.0 is historical and does not establish current crop bonuses. No planting loop, blueprint purchase or conversion payout was playtested.', '2026年11月2日核对10月27日发布的10月29日公告。10月15日 v1.0.3732728.0 是历史依据，不能确认当前作物增益。未实测种植循环、蓝图购买或转换到账。', '2026年11月2日核對10月27日發布的10月29日公告。10月15日 v1.0.3732728.0 是歷史依據，不能確認目前作物增益。未實測種植循環、藍圖購買或轉換到帳。') },
    ],
  };
  if (slug === 'aniimo-holo-battle-interlink') return {
    title: t('Aniimo Holo-Battle Interlink: Pick a Route & Claim Stars', '伊莫 Holo-Battle Interlink：选路线与领取星级奖励', '伊莫 Holo-Battle Interlink：選路線與領取星級獎勵'),
    subtitle: t('Use the Part 2 independent routes, solo/team options and manual reward checks without inventing a best lineup.', '按后半段独立路线、单人／组队入口与手动领奖规则规划周常。', '按後半段獨立路線、單人／組隊入口與手動領獎規則規劃週常。'),
    tag: t('Weekly mode', '每周模式', '每週模式'),
    lead: t('After October 29, left, middle and right paths are independent gameplay instances. Choose the path you need, inspect its current mechanics, and claim the phase’s star rewards manually. The older four-player summary alone no longer describes every entry option.', '10月29日后，左、中、右路为独立玩法副本。先选需要的路线、阅读当期机制，完成后手动领取本期星级奖励；旧版四人合作概述不能完整代表现有入口。', '10月29日後，左、中、右路為獨立玩法副本。先選需要的路線、閱讀當期機制，完成後手動領取本期星級獎勵；舊版四人合作概述不能完整代表現有入口。'),
    body: [
      { t: 'h', c: t('1. Check weekly access before forming a party', '1. 组队前核对开放条件', '1. 組隊前核對開放條件') },
      { t: 'p', c: t('Trailblazer I remains the announced title requirement. The October 29 notice lists Thursday 04:00 to the following Monday 03:59. This segment does not explicitly label separate server timezones; verify the timer in your server interface instead of assuming UTC+8 applies worldwide.', '公告条件仍为 Trailblazer I；10月29日公告列每周四04:00至下周一03:59。该段未明确逐服时区，请核对所在服界面倒计时，不把 UTC+8 套用到全球。', '公告條件仍為 Trailblazer I；10月29日公告列每週四04:00至下週一03:59。該段未明確逐服時區，請核對所在服介面倒數計時，不把 UTC+8 套用到全球。') },
      { t: 'h', c: t('2. Match the path to the job', '2. 按目标选择路线', '2. 按目標選擇路線') },
      { t: 'table', head: [t('Before / after a run', '开打前／结束后', '開打前／結束後'), t('Part 2 rule', '后半段规则', '後半段規則'), t('Action', '操作检查', '操作檢查')], rows: [
        [t('Choose a path', '选择路线', '選擇路線'), t('Left, middle and right are independent; each supports matching, team or solo entry.', '左、中、右路独立，可分别匹配、组队或单人进入。', '左、中、右路獨立，可分別配對、組隊或單人進入。'), t('Confirm the selected path with teammates, rather than assuming one queue covers all three.', '与队友核对选中路线，不假设一次排队涵盖三路。', '與隊友核對選中路線，不假設一次排隊涵蓋三路。')],
        [t('Read the encounter', '阅读遭遇机制', '閱讀遭遇機制'), t('New Alphas and environmental effects, adjusted phase buffs and reset season buffs.', '新增 Alpha 与环境效果、调整本期增益并重置赛季增益。', '新增 Alpha 與環境效果、調整本期增益並重設賽季增益。'), t('Read the current panel before reusing an old lineup or buff plan.', '沿用旧队伍或增益方案前，先读当前面板。', '沿用舊隊伍或增益方案前，先讀目前面板。')],
        [t('Check star progress', '查看星级进度', '查看星級進度'), t('Each path retains its own highest star rating; extra stars and total-star rewards were updated.', '各路分别记录最高星级，并新增额外星级、更新总星奖励。', '各路分別記錄最高星級，並新增額外星級、更新總星獎勵。'), t('Compare the missing stars per path with the current milestone, not an older fixed reward table.', '对照各路缺星与当前里程碑，不沿用旧固定奖励表。', '對照各路缺星與目前里程碑，不沿用舊固定獎勵表。')],
        [t('Claim rewards', '领取奖励', '領取獎勵'), t('Each phase’s star rewards must now be claimed manually.', '本期星级奖励现在需要手动领取。', '本期星級獎勵現在需要手動領取。'), t('Open the reward panel after improving stars; completion alone does not confirm delivery.', '提升星级后打开领奖面板，完成挑战不等于已到账。', '提升星級後開啟領獎面板，完成挑戰不等於已到帳。')],
      ] },
      { t: 'h', c: t('3. A teammate left or rewards look missing?', '3. 队友离开或奖励似乎缺失？', '3. 隊友離開或獎勵似乎缺失？') },
      { t: 'p', c: t('For the Holo Training Ace achievement specifically, November 5 v1.1.3880756.0 fixes failure to unlock after completing the current season’s highest training difficulty. Distinguish that achievement from manually claimed star rewards. Update and inspect the achievement state; the notice does not promise automatic retroactive delivery or specify a mandatory rerun.', '针对 Holo Training Ace 成就，11月5日 v1.1.3880756.0 修复了完成当季最高训练难度后无法解锁的问题。成就与手动领取的星级奖励要分开核对；更新后检查成就状态。公告没有承诺自动追溯补发，也没有说明必须重打一遍。', '針對 Holo Training Ace 成就，11月5日 v1.1.3880756.0 修正了完成當季最高訓練難度後無法解鎖的問題。成就與手動領取的星級獎勵要分開核對；更新後檢查成就狀態。公告沒有承諾自動追溯補發，也沒有說明必須重打一遍。') },
      { t: 'link', href: sourceById.get('aniimo-patch-1-1-3880756-2026-11-05')!.url, c: t('Read the November 5 achievement fix', '查看11月5日成就修复原文', '查看11月5日成就修正原文') },
      { t: 'p', c: t('The new notice adds AI assistance when someone leaves during preparation; it does not promise every mid-battle disconnect is replaced. For a reward report, record the path, phase, highest stars and manual-claim screen. Check the selected route and claim state before assuming a lost reward.', '新公告说明准备阶段有人离开时加入 AI 协助，不保证所有战斗中断线都会补位。反馈奖励问题时记录路线、本期、最高星级与手动领取界面；先核对路线和领取状态，再判断是否丢失。', '新公告說明準備階段有人離開時加入 AI 協助，不保證所有戰鬥中斷線都會補位。回報獎勵問題時記錄路線、本期、最高星級與手動領取介面；先核對路線和領取狀態，再判斷是否遺失。') },
      { t: 'link', href: '/guide/aniimo-team-composition', c: t('Compare published roles and mobility without a fabricated best build', '按已公布定位与移动能力比较队伍', '按已公布定位與移動能力比較隊伍') },
      { t: 'link', href: '/guide/aniimo-launch-checklist-known-issues', c: t('Report a reproducible current-version issue', '反馈可复现的当前版本问题', '回報可重現的目前版本問題') },
      { t: 'quote', c: t('Reviewed November 2, 2026 using the October 27 announcement for October 29. No live-cycle Alpha list, numeric milestone payouts, optimal party or combat route was tested. September rules remain historical source context, not proof of every current option.', '2026年11月2日核对10月27日发布的10月29日公告。未实测当期 Alpha 名单、具体里程碑奖励、最优队伍或战斗路线。9月规则只作历史来源，不代表现有全部选项。', '2026年11月2日核對10月27日發布的10月29日公告。未實測當期 Alpha 名單、具體里程碑獎勵、最佳隊伍或戰鬥路線。9月規則只作歷史來源，不代表現有全部選項。') },
    ],
  };
  if (slug === 'aniimo-version-1-1-update') return {
    title: t('Aniimo S1 Part 2: Whisperwake Unlock & Level 60–70 Checklist', '伊莫 S1 后半段：Whisperwake 解锁与60–70级成长清单', '伊莫 S1 後半段：Whisperwake 解鎖與60–70級成長清單'),
    subtitle: t('Find the next progression gate: island story, title assessment, Ascension or Resonance Star Up.', '区分岛屿剧情、称号考核、Ascension 与 Resonance Star Up，找到下一步成长条件。', '區分島嶼劇情、稱號考核、Ascension 與 Resonance Star Up，找到下一步成長條件。'),
    tag: t('Progression', '成长清单', '成長清單'),
    lead: t('For the October 29 update, check story access before spending growth materials. Reaching level 60 does not by itself complete the island story or unlock every level cap. Use the table to identify which gate is blocking your next goal.', '10月29日更新后，先核对剧情入口，再消耗养成材料。达到60级本身不等于完成岛屿剧情或解除所有等级上限；按下表定位当前目标被哪项条件阻挡。', '10月29日更新後，先核對劇情入口，再消耗養成材料。達到60級本身不等於完成島嶼劇情或解除所有等級上限；按下表定位目前目標被哪項條件阻擋。'),
    body: [
      { t: 'h', c: t('Start here: which goal is blocked?', '先定位：你卡在哪个目标？', '先定位：你卡在哪個目標？') },
      { t: 'link', href: sourceById.get('aniimo-s1-part-two-2026-10-27')!.url, c: t('Checklist updated November 3: October 29 growth announcement', '11月3日更新检查流程：查看10月29日成长公告', '11月3日更新檢查流程：查看10月29日成長公告') },
      { t: 'p', c: t('Choose one branch; these are separate systems, not a single mandatory route. The checks below organize the October 29 announcement and do not establish a complete quest chain or the exact client interface.', '选择一个分支检查；它们是不同系统，不是一条必须依次走完的路线。以下按10月29日公告整理，不代表完整任务链或已实测客户端界面。', '選擇一個分支檢查；它們是不同系統，不是一條必須依次走完的路線。以下按10月29日公告整理，不代表完整任務鏈或已實測客戶端介面。') },
      { t: 'table', head: [t('Blocked goal', '当前目标', '目前目標'), t('Decision path', '判断流程', '判斷流程'), t('Before spending', '消耗前检查', '消耗前檢查')], rows: [
        [t('Enter Whisperwake Isles', '进入 Whisperwake Isles', '進入 Whisperwake Isles'), t('Follow the current prerequisite story objective. If the map already opens but First Visit does not, check A Tale of Tide and Song for that event separately.', '先查当前前置剧情目标；若地图已开但 First Visit 未开，单独核对活动要求的 A Tale of Tide and Song。', '先查目前前置劇情目標；若地圖已開但 First Visit 未開，單獨核對活動要求的 A Tale of Tide and Song。'), t('A level-up item is not evidence that a story gate is complete.', '升级道具不能证明剧情条件已完成。', '升級道具不能證明劇情條件已完成。')],
        [t('Raise an Aniimo beyond level 60', '伊莫突破60级', '伊莫突破60級'), t('Trailblazer II promotion incomplete? Check the assessment. Already promoted? Check this Aniimo’s Ascension and main-element Evolution Item.', '未完成 Trailblazer II 晋升？先查考核；已晋升？再查该伊莫的 Ascension 与主元素 Evolution Item。', '未完成 Trailblazer II 晉升？先查考核；已晉升？再查該伊莫的 Ascension 與主元素 Evolution Item。'), t('Confirm the individual and its main element. A raised account cap does not remove the individual Ascension requirement.', '确认个体及主元素；上限已开不代表免除个体 Ascension。', '確認個體及主元素；上限已開不代表免除個體 Ascension。')],
        [t('Raise character or Aniimo beyond level 65', '角色或伊莫突破65级', '角色或伊莫突破65級'), t('Check Trailblazer III promotion first, then the growth requirements shown for the selected target.', '先查 Trailblazer III 晋升，再查所选目标面板的养成条件。', '先查 Trailblazer III 晉升，再查所選目標面板的養成條件。'), t('Potential Reset Card resets Capability Awakening above level 60; it does not grant a title promotion.', 'Potential Reset Card 用于60级以上 Capability Awakening 重置，不用于称号晋升。', 'Potential Reset Card 用於60級以上 Capability Awakening 重置，不用於稱號晉升。')],
        ['Stellar Tier 6', t('Is this Aniimo level 65? If not, resolve leveling first. If yes, inspect Resonance Star Up and compatible materials.', '该伊莫已65级？未达到先处理等级；已达到再查 Resonance Star Up 与适用材料。', '該伊莫已65級？未達到先處理等級；已達到再查 Resonance Star Up 與適用材料。'), t('Check this individual’s Season Tag before applying the any-region Dewdrop Crystal rule.', '使用任意区域 Dewdrop Crystal 规则前，核对该个体的 Season Tag。', '使用任意區域 Dewdrop Crystal 規則前，核對該個體的 Season Tag。')],
      ] },
      { t: 'p', c: t('If the displayed conditions appear satisfied but the action remains locked, keep the character level/title, target Aniimo level, exact lock text and client version for official support. Do not repeatedly reset Potential to test whether it opens an unrelated gate.', '若面板条件看似已满足仍锁定，记录角色等级与称号、目标伊莫等级、锁定提示原文和版本，交给官方支持核对；不要反复重置潜能来试解不相关的门槛。', '若面板條件看似已滿足仍鎖定，記錄角色等級與稱號、目標伊莫等級、鎖定提示原文和版本，交給官方支援核對；不要反覆重設潛能來試解不相關的門檻。') },
      { t: 'h', c: t('1. Separate map access from event eligibility', '1. 区分地图入口与活动资格', '1. 區分地圖入口與活動資格') },
      { t: 'p', c: t('Whisperwake Isles has four announced areas: Crescent Bay, Rosy Mirelands, Wildwater Gorge and Cloudreach Falls. Related content unlocks automatically after prerequisite story quests. The announcement does not supply a complete quest chain or a verified travel route; follow the current story objective rather than an invented NPC or coordinate.', 'Whisperwake Isles 本次开放 Crescent Bay、Rosy Mirelands、Wildwater Gorge、Cloudreach Falls 四区；完成前置剧情后自动开放相关内容。公告没有给出完整任务链或实测传送路线，请沿当前剧情目标推进，不凭空指定 NPC 或坐标。', 'Whisperwake Isles 本次開放 Crescent Bay、Rosy Mirelands、Wildwater Gorge、Cloudreach Falls 四區；完成前置劇情後自動開放相關內容。公告沒有給出完整任務鏈或實測傳送路線，請沿目前劇情目標推進，不憑空指定 NPC 或座標。') },
      { t: 'p', c: t('First Visit to Whisperwake Isles separately requires A Tale of Tide and Song. That is the survey event requirement, not proof it is the universal map-entry quest. If the map opens but the survey does not, compare the activity requirement with your completed quest log.', 'First Visit to Whisperwake Isles 活动单独要求完成 A Tale of Tide and Song。这是调查活动资格，不能直接当作所有玩家的地图入口任务；地图已开但调查未开时，对照活动条件与已完成任务记录。', 'First Visit to Whisperwake Isles 活動單獨要求完成 A Tale of Tide and Song。這是調查活動資格，不能直接當作所有玩家的地圖入口任務；地圖已開但調查未開時，對照活動條件與已完成任務紀錄。') },
      { t: 'h', c: t('2. Match the blocked goal to its gate', '2. 按目标核对成长门槛', '2. 按目標核對成長門檻') },
      { t: 'table', head: [t('Goal', '目标', '目標'), t('Announced requirement', '公告条件', '公告條件'), t('Next check', '下一步核对', '下一步核對')], rows: [
        [t('New title assessments', '新称号考核', '新稱號考核'), t('Dr. Lewis contacts characters at level 60 or higher for Trailblazer II / III and Badge Challenges.', '角色60级及以上，Dr. Lewis 联系开启 Trailblazer II／III 与 Badge Challenges。', '角色60級及以上，Dr. Lewis 聯絡開啟 Trailblazer II／III 與 Badge Challenges。'), t('Look for the assessment contact; level alone is not a completed promotion.', '查找考核联系；达到等级不等于晋升完成。', '查找考核聯絡；達到等級不等於晉升完成。')],
        ['Chapter of Whisperwake', t('Trailblazer I plus advancing the island story.', 'Trailblazer I，并推进岛屿剧情。', 'Trailblazer I，並推進島嶼劇情。'), t('Check both title and story, not just character level.', '同时核对称号与剧情，不只看角色等级。', '同時核對稱號與劇情，不只看角色等級。')],
        [t('Aniimo 60 → 65', '伊莫60 → 65', '伊莫60 → 65'), 'Trailblazer II', t('After level 60, Ascension also consumes an Evolution Item of the main element.', '60级后还需 Ascension，消耗主元素对应 Evolution Item。', '60級後還需 Ascension，消耗主元素對應 Evolution Item。')],
        [t('Character / Aniimo 65 → 70', '角色／伊莫65 → 70', '角色／伊莫65 → 70'), 'Trailblazer III', t('A raised cap does not replace the individual Aniimo growth requirements.', '上限提高不代表免除个体养成条件。', '上限提高不代表免除個體養成條件。')],
        ['Stellar Tier 6', t('Aniimo level 65; Resonance Star Up.', '伊莫65级，通过 Resonance Star Up 突破。', '伊莫65級，透過 Resonance Star Up 突破。'), t('Check material compatibility and the final confirmation preview.', '核对材料适用范围与最终确认预览。', '核對材料適用範圍與最終確認預覽。')],
      ] },
      { t: 'h', c: t('3. Spend only for the blocked system', '3. 只为对应系统消耗材料', '3. 只為對應系統消耗材料') },
      { t: 'p', c: t('Capability Awakening resets above level 60 use a Potential Reset Card. Level increases and Resonance breakthroughs increase awakening count; a reset is not a substitute for a title promotion. A Season Tag allows Dewdrop Crystal from any region for Resonance Star Up. Verify that tag on this individual before using an otherwise regional material.', '60级以上重置 Capability Awakening 使用 Potential Reset Card；升级和共鸣突破可增加觉醒次数，重置不能替代称号晋升。带 Season Tag 的伊莫可用任意区域 Dewdrop Crystal 做 Resonance Star Up，使用跨区材料前先核对该个体标签。', '60級以上重置 Capability Awakening 使用 Potential Reset Card；升級和共鳴突破可增加覺醒次數，重置不能替代稱號晉升。帶 Season Tag 的伊莫可用任意區域 Dewdrop Crystal 做 Resonance Star Up，使用跨區材料前先核對該個體標籤。') },
      { t: 'link', href: '/guide/aniimo-prismana-potential-breeding-guide', c: t('Choose growth, form or hue items by their actual effect', '按实际效果区分成长、形态和色彩道具', '按實際效果區分成長、形態和色彩道具') },
      { t: 'link', href: '/guide/aniimo-prismana-event-tracker', c: t('After unlocking an area, choose the correct November rotation', '区域开放后，选择对应11月轮换', '區域開放後，選擇對應11月輪換') },
      { t: 'link', href: '/guide/aniimo-launch-checklist-known-issues', c: t('Waterfall Climb or mechanism objective blocked? Check the October 30 fixes', 'Waterfall Climb 或机关目标卡住？核对10月30日修复', 'Waterfall Climb 或機關目標卡住？核對10月30日修正') },
      { t: 'quote', c: t('Checked November 1, 2026 against the October 27 announcement for October 29. This existing version URL now prioritizes Part 2 progression; September compensation notices are not current claims. No complete quest walkthrough, material quantities or optimal farming route has been verified.', '2026年11月1日核对10月27日发布的10月29日更新公告。原版本页现优先解决后半段成长问题，不把9月补偿当作当前可领。未核验完整任务攻略、材料数量或最优刷取路线。', '2026年11月1日核對10月27日發布的10月29日更新公告。原版本頁現優先解決後半段成長問題，不把9月補償當作目前可領。未核驗完整任務攻略、材料數量或最佳刷取路線。') },
    ],
  };
  if (slug === 'aniimo-egg-heist') return {
    title: t('Aniimo Egg Heist: Fair PVP vs PVE / Chaos', '伊莫 Egg Heist：公平 PVP 与 PVE／Chaos 怎么选', '伊莫 Egg Heist：公平 PVP 與 PVE／Chaos 怎麼選'),
    subtitle: t('Compare entry gates, Giga-Egg victory rules, equipment limits and post-update egg delivery.', '对照参与条件、Giga-Egg 胜负判定、装备限制与更新后蛋的去向。', '對照參與條件、Giga-Egg 勝負判定、裝備限制與更新後蛋的去向。'),
    tag: 'Egg Heist',
    lead: t('Choose the mode before preparing a loadout. The October 29 fair PVP test has three competing teams and balanced deployed stats; it is different from the existing PVE / Chaos progression. The final Twine owner wins, not necessarily the team that built most activation.', '先选模式，再准备装备。10月29日新增公平 PVP 测试为三队争夺、出战属性平衡调整，与既有 PVE／Chaos 成长玩法不同。最终 Twine 归属决定胜负，不是累计激活最多的队伍必胜。', '先選模式，再準備裝備。10月29日新增公平 PVP 測試為三隊爭奪、出戰屬性平衡調整，與既有 PVE／Chaos 成長玩法不同。最終 Twine 歸屬決定勝負，不是累計啟用最多的隊伍必勝。'),
    body: [
      ...getNovember12Blocks(locale, true),
      ...getNovemberFixBlocks(locale, true),
      { t: 'h', c: t('1. Select the ruleset', '1. 先选规则组', '1. 先選規則組') },
      { t: 'table', head: [t('Mode', '模式', '模式'), t('Entry / preparation', '入口／准备', '入口／準備'), t('Decision', '选择依据', '選擇依據')], rows: [
        [t('Fair PVP test', '公平 PVP 测试', '公平 PVP 測試'), t('Character level 50 + Rising Egg Scout; announced daily 18:00–24:00. The segment does not clearly specify an absolute timezone: check your server panel.', '角色50级＋Rising Egg Scout；公告每天18:00–24:00，该段未明确绝对时区，请查所在服面板。', '角色50級＋Rising Egg Scout；公告每天18:00–24:00，該段未明確絕對時區，請查所在服面板。'), t('No configured equipment loadout or carried items; deployed stats adjusted. Prepare for Twine ownership, not a gear advantage.', '不允许配置装备或带入物品，出战属性会调整；围绕 Twine 归属准备，不能套用装备优势。', '不允許配置裝備或帶入物品，出戰屬性會調整；圍繞 Twine 歸屬準備，不能套用裝備優勢。')],
        ['PVE / Chaos', t('Check the current difficulty panel. September 23 rules list Elite Egg Seeker Tier IV + Chaos Ticket for Chaos; these are not the fair PVP entry gate.', '核对当前难度面板。9月23日规则列 Chaos 要求 Elite Egg Seeker Tier IV＋Chaos Ticket，不是公平 PVP 门槛。', '核對目前難度面板。9月23日規則列 Chaos 要求 Elite Egg Seeker Tier IV＋Chaos Ticket，不是公平 PVP 門檻。'), t('Use difficulty-specific combat and recovery rules; higher announced reward chances do not establish exact drop rates or a fastest route.', '按难度处理战斗与恢复；公告奖励概率提高不能推导具体掉率或最快路线。', '按難度處理戰鬥與恢復；公告獎勵機率提高不能推導具體掉率或最快路線。')],
      ] },
      { t: 'h', c: t('2. Understand the Giga-Egg finish condition', '2. 理解 Giga-Egg 终局判定', '2. 理解 Giga-Egg 終局判定') },
      { t: 'p', c: t('November 5 v1.1.3880756.0 fixes wind affecting the Giga-Egg in unintended ways. Do not reuse an older wind-interaction trick as a verified current strategy. This note publishes no replacement wind mechanic and does not announce a change to the finish condition below.', '11月5日 v1.1.3880756.0 修复风对 Giga-Egg 的非预期影响。不要把旧视频里的风交互技巧直接当作现行有效策略。该条没有公布替代风机制，也没有宣布修改下方终局判定。', '11月5日 v1.1.3880756.0 修正風對 Giga-Egg 的非預期影響。不要把舊影片裡的風互動技巧直接當作現行有效策略。該條沒有公布替代風機制，也沒有宣布修改下方終局判定。') },
      { t: 'link', href: sourceById.get('aniimo-patch-1-1-3880756-2026-11-05')!.url, c: t('Read the November 5 Giga-Egg fix', '查看11月5日 Giga-Egg 修复原文', '查看11月5日 Giga-Egg 修正原文') },
      { t: 'p', c: t('Maintaining Twine with the Giga-Egg accumulates activation. At 100% or match end, the team currently in Twine wins. Before the finish, check current ownership rather than treating an earlier lead as secured. Every winning member receives one Giga-Egg, guaranteeing an Umbral Egg with a small chance of a Prismana Egg; no numeric rate is published. Teams meeting an activation threshold can receive a Chest, but this source gives no numeric threshold or guaranteed collectible.', '维持与 Giga-Egg 的 Twine 会累积激活值；达到100%或比赛结束时，当前保持 Twine 的队伍获胜。终局前应核对当前归属，不能把前期领先当作已赢。胜队每人1枚 Giga-Egg，保证 Umbral Egg，并有小概率 Prismana Egg，未公布数值掉率。达到一定激活值的队伍可得 Chest，但该来源没有给出具体阈值或藏品保底。', '維持與 Giga-Egg 的 Twine 會累積啟用值；達到100%或比賽結束時，目前保持 Twine 的隊伍獲勝。終局前應核對目前歸屬，不能把前期領先當作已贏。勝隊每人1枚 Giga-Egg，保證 Umbral Egg，並有小機率 Prismana Egg，未公布數值掉率。達到一定啟用值的隊伍可得 Chest，但該來源沒有給出具體門檻或藏品保底。') },
      { t: 'h', c: t('3. PVE recovery and collection checks', '3. PVE 恢复与收集检查', '3. PVE 恢復與收集檢查') },
      { t: 'li', c: t('Umbral P.DEF and melee Protective Unit durability consumption were reduced. Basic Berserker Chip restores Pathfinder HP when dealing damage to nearby enemies; this is not a universal Aniimo heal.', 'Umbral P.DEF 与近战 Protective Unit 耐久消耗降低。Basic Berserker Chip 对附近敌人造成伤害时恢复的是玩家 HP，不能写成全队伊莫通用治疗。', 'Umbral P.DEF 與近戰 Protective Unit 耐久消耗降低。Basic Berserker Chip 對附近敵人造成傷害時恢復的是玩家 HP，不能寫成全隊伊莫通用治療。') },
      { t: 'li', c: t('Defeating Umbral Bubbeep grants continuous HP recovery; escaping Umbral Baleetle restores all Pathfinder HP. Identify the mechanic before spending a recovery resource.', '击败 Umbral Bubbeep 获得持续 HP 恢复；挣脱 Umbral Baleetle 恢复玩家全部 HP。先识别机制，再决定是否消耗恢复资源。', '擊敗 Umbral Bubbeep 獲得持續 HP 恢復；掙脫 Umbral Baleetle 恢復玩家全部 HP。先識別機制，再決定是否消耗恢復資源。') },
      { t: 'li', c: t('Umbral Bouldus has an announced fixed room, but no room route is verified here. October 30 v1.1.3857679.0 reduces its detection range and stops HP resetting on leaving combat; do not infer a guaranteed easy route.', 'Umbral Bouldus 公告有固定房间，本站未核验房间路线。10月30日 v1.1.3857679.0 缩小侦测范围，并不再脱战回满血；不能由此保证简单速刷。', 'Umbral Bouldus 公告有固定房間，本站未核驗房間路線。10月30日 v1.1.3857679.0 縮小偵測範圍，並不再脫戰回滿血；不能由此保證簡單速刷。') },
      { t: 'p', c: t('Only newly obtained Mysterious Prismana Egg, Umbral Aniimo Egg and Ruins Aniimo Egg after the update are announced to include Whisperwake Aniimo. Do not assume old stored eggs gained that pool. Settlement eggs go directly to Inventory Warehouse; check the settlement preview and warehouse before looking for mail or reporting a missing reward.', '公告明确是更新后新获得的 Mysterious Prismana Egg、Umbral Aniimo Egg、Ruins Aniimo Egg 可孵出 Whisperwake 伊莫，不能推定旧库存自动扩池。结算蛋直接进入 Inventory Warehouse；先查结算预览和仓库，再查邮件或报告奖励丢失。', '公告明確是更新後新獲得的 Mysterious Prismana Egg、Umbral Aniimo Egg、Ruins Aniimo Egg 可孵出 Whisperwake 伊莫，不能推定舊庫存自動擴池。結算蛋直接進入 Inventory Warehouse；先查結算預覽和倉庫，再查郵件或回報獎勵遺失。') },
      { t: 'link', href: '/guide/aniimo-prismana-potential-breeding-guide', c: t('Egg rewards, Sparkling style and Potential are different decisions', '蛋奖励、Sparkling 样式与潜能是不同选择', '蛋獎勵、Sparkling 樣式與潛能是不同選擇') },
      { t: 'quote', c: t('Checked November 1, 2026 using the October 27 announcement and October 30 patch. No live match, loot sample or optimum team was tested. The following Erlath guidance and Dev Feedback | Oct 13 / October 15 v1.0.3732728.0 references are dated history, not the latest patch.', '2026年11月1日核对10月27日公告与10月30日补丁。未实测对局、掉落样本或最优队伍。下方 Erlath 说明与 Dev Feedback | Oct 13／10月15日 v1.0.3732728.0 是历史记录，不是最新补丁。', '2026年11月1日核對10月27日公告與10月30日補丁。未實測對局、掉落樣本或最佳隊伍。下方 Erlath 說明與 Dev Feedback | Oct 13／10月15日 v1.0.3732728.0 是歷史紀錄，不是最新補丁。') },
    ],
  };
  if (slug === 'aniimo-prismana-potential-breeding-guide') return {
    title: t('Aniimo Hue & Growth Items: What Changes Potential?', '伊莫色彩与养成道具：哪些操作影响潜能？', '伊莫色彩與養成道具：哪些操作影響潛能？'),
    subtitle: t('Check your target before spending: unlocked hues, random Pigment, excluded Legendary Aniipod targets and unchanged Acquired Potential.', '消耗前按目标核对：个体已解锁色彩、随机 Pigment、传奇球排除对象与不变的 Acquired Potential。', '消耗前按目標核對：個體已解鎖色彩、隨機 Pigment、傳說球排除對象與不變的 Acquired Potential。'),
    tag: t('Item decisions', '道具选择', '道具選擇'),
    lead: t('Choose the result first: a different unlocked hue, a new random hue, an exclusive pod effect, a form change or growth progression. These are separate systems. The October 29 update expressly says replacing a Legendary Aniipod does not change Acquired Potential.', '先确定目标：切换已解锁色彩、随机开新色、获得专属球效果、转换形态，还是推进养成。这些属于不同系统；10月29日更新明确说，替换传奇 Aniipod 不改变 Acquired Potential。', '先確定目標：切換已解鎖色彩、隨機開新色、獲得專屬球效果、轉換形態，還是推進養成。這些屬於不同系統；10月29日更新明確說，替換傳說 Aniipod 不改變 Acquired Potential。'),
    body: [
      { t: 'sparklingDecision' },
      { t: 'h', c: t('1. Match the action to the desired result', '1. 按目标选操作', '1. 按目標選操作') },
      { t: 'table', head: [t('Goal / action', '目标／操作', '目標／操作'), t('Cost or condition', '消耗或条件', '消耗或條件'), t('Limit to check before confirming', '确认前核对限制', '確認前核對限制')], rows: [
        ['Hue Swap', t('Credits; an unlocked hue on this same individual.', 'Credits；该个体已解锁色彩。', 'Credits；該個體已解鎖色彩。'), t('Unlocks are individual-specific, not shared by the species. Compare unlocked previews before rerolling.', '解锁只对同一个体有效，不在同物种间共享；先查已解锁预览，再决定是否重洗。', '解鎖只對同一個體有效，不在同物種間共享；先查已解鎖預覽，再決定是否重洗。')],
        ['Hue Reroll / Sparkling Pigment', t('Random hue unlock / reroll.', '随机解锁／重洗色彩。', '隨機解鎖／重洗色彩。'), t('Not a selector for any desired hue. A duplicate returns 2 Sparkling Sigil, not a guaranteed new hue.', '不是任意选色券；重复返回2枚 Sparkling Sigil，不保证新色。', '不是任意選色券；重複返回2枚 Sparkling Sigil，不保證新色。')],
        ['Use Legendary Aniipod', t('Eligible Sparkling Aniimo; replaces its bound Aniipod and grants the exclusive effect.', '符合条件的 Sparkling 伊莫；替换绑定 Aniipod 并赋予专属效果。', '符合條件的 Sparkling 伊莫；替換綁定 Aniipod 並賦予專屬效果。'), t('Acquired Potential does not change. Cannot use on Irisalis, Helion or Lunara.', '不改变 Acquired Potential；不能用于 Irisalis、Helion、Lunara。', '不改變 Acquired Potential；不能用於 Irisalis、Helion、Lunara。')],
        ['Prismana Orb', t('Form conversion; inspect exact item and eligible target.', '转换形态；核对准确道具及适用目标。', '轉換形態；核對準確道具及適用目標。'), t('The notice lists broadened orb use, a Whisperwake Isles variant and a global orb with overlapping names. Verify the current item description; do not assume every orb is interchangeable.', '公告同时列旧球适用范围扩大、Whisperwake Isles 版与全区域球，名称有重叠；以当前道具说明确认，不能假设全部通用。', '公告同時列舊球適用範圍擴大、Whisperwake Isles 版與全區域球，名稱有重疊；以目前道具說明確認，不能假設全部通用。')],
        ['Potential Reset Card', t('Capability Awakening reset after Aniimo exceeds level 60.', '伊莫超过60级后重置 Capability Awakening。', '伊莫超過60級後重置 Capability Awakening。'), t('Not a hue or form-change item, and no guaranteed perfect result is established here.', '不是换色或变形道具，本站没有确认必得满潜结果。', '不是換色或變形道具，本站沒有確認必得滿潛結果。')],
        ['Dewdrop Crystal / Mark of the Strong', t('Resonance Star Up / re-contract a held item, respectively.', '分别用于 Resonance Star Up／重新契约 Held Item。', '分別用於 Resonance Star Up／重新契約 Held Item。'), t('Season Tag allows any-region crystals; Mark of the Strong is now merged across regions. Check the tag and target rather than treating these as cosmetic materials.', 'Season Tag 可用任意区域晶体；Mark of the Strong 已跨区合并。核对标签和目标，不把这些当外观材料。', 'Season Tag 可用任意區域晶體；Mark of the Strong 已跨區合併。核對標籤和目標，不把這些當外觀材料。')],
      ] },
      { t: 'h', c: t('2. Before spending Pigment', '2. 消耗 Pigment 前', '2. 消耗 Pigment 前') },
      { t: 'p', c: t('Open Sparkling Hue and check this individual: Sparkle Infusion, Hue Reroll, Hue Swap and Use Legendary Aniipod are separate controls. Catching an individual with a hue unlocks it for that individual. Sparkling Original adds the initial color with Sparkling effects and is available to any Sparkling Aniimo; compare that preview before pursuing a random alternative. Hue Swap uses Credits, so free switching in the older plan should not be read as zero cost.', '打开 Sparkling Hue，确认是目标个体：Sparkle Infusion、Hue Reroll、Hue Swap、Use Legendary Aniipod 是不同操作。捕获带某色彩的个体，会为该个体解锁该色。Sparkling Original 是带闪光效果的初始配色，任意 Sparkling 伊莫可获得；追求随机新色前先看预览。Hue Swap 消耗 Credits，不能把旧计划中的自由切换理解为零费用。', '開啟 Sparkling Hue，確認是目標個體：Sparkle Infusion、Hue Reroll、Hue Swap、Use Legendary Aniipod 是不同操作。捕獲帶某色彩的個體，會為該個體解鎖該色。Sparkling Original 是帶閃光效果的初始配色，任意 Sparkling 伊莫可獲得；追求隨機新色前先看預覽。Hue Swap 消耗 Credits，不能把舊計畫中的自由切換理解為零費用。') },
      { t: 'p', c: t('Reroll Record covers results after the update for the most recent three months. A missing older roll is not evidence it never happened. The notice promises reissued Sigils for pre-update duplicates; check private account mail rather than assuming every account has received them. No hue odds or expected reroll budget is derived here.', 'Reroll Record 记录更新后最近3个月结果，旧记录缺失不代表从未重洗。公告说明会补发更新前重复色对应 Sigil，请查账号邮件，不能假设所有账号已到账。本站不推算未公布的颜色概率或预期洗色预算。', 'Reroll Record 記錄更新後最近3個月結果，舊紀錄缺失不代表從未重洗。公告說明會補發更新前重複色對應 Sigil，請查帳號郵件，不能假設所有帳號已到帳。本站不推算未公布的顏色機率或預期洗色預算。') },
      { t: 'h', c: t('3. Appearance is not a Potential guarantee', '3. 外观不是潜能保证', '3. 外觀不是潛能保證') },
      { t: 'p', c: t('Prismana morphology, Sparkling style and an individual’s Potential are different records. A form label alone does not prove perfect stats or a breeding outcome. The adjusted orb description preserves Acquired Potential, Mutation and Personality; it does not promise an upgrade to perfect values. No complete breeding recipe or universal best spending order is established here.', 'Prismana 形态、Sparkling 样式和个体潜能是不同记录，单凭形态标签不能保证满属性或繁育结果。调整后的球说明保留 Acquired Potential、Mutation、Personality，并不承诺提升到满值。本站没有确认完整繁育配方或通用最优消费顺序。', 'Prismana 形態、Sparkling 樣式和個體潛能是不同紀錄，單憑形態標籤不能保證滿屬性或繁育結果。調整後的球說明保留 Acquired Potential、Mutation、Personality，並不承諾提升到滿值。本站沒有確認完整繁育配方或通用最佳消費順序。') },
      { t: 'link', href: '/guide/aniimo-forms-explained', c: t('Identify morphology before comparing Sparkling styles', '先识别形态，再比较 Sparkling 样式', '先識別形態，再比較 Sparkling 樣式') },
      { t: 'link', href: '/guide/aniimo-version-1-1-update', c: t('Level cap blocked? Use the 60–70 progression checklist', '等级上限卡住？查看60–70级成长清单', '等級上限卡住？查看60–70級成長清單') },
      { t: 'quote', c: t('Official October 27 announcement for the October 29 update, rechecked November 3, 2026. This supersedes October 1 plans only for the features expressly listed. No purchase prices, random hue distribution or live-client test is claimed.', '10月27日发布的10月29日更新公告，2026年11月3日重新核对；仅对明确列出的功能替代10月1日计划状态。未核验购买价格、随机色分布或客户端实测。', '10月27日發布的10月29日更新公告，2026年11月3日重新核對；僅對明確列出的功能替代10月1日計畫狀態。未核驗購買價格、隨機色分布或客戶端實測。') },
    ],
  };
  if (slug === 'aniimo-prismana-event-tracker') return {
    title: t('Aniimo Dash, Prismana Snapshots & Event Schedule', '伊莫活动：Aniimo Dash、Prismana Snapshots 与排期', '伊莫活動：Aniimo Dash、Prismana Snapshots 與排期'),
    subtitle: t('Choose a racing mode, check track dates and server deadlines, then distinguish regular and special photo rewards.', '选择竞速模式、核对赛道日期与分服截止，再区分普通和特殊摄影奖励。', '選擇競速模式、核對賽道日期與分服截止，再區分普通和特殊攝影獎勵。'),
    tag: t('Limited events', '限时活动', '限時活動'),
    lead: t('Aniimo Dash requires Lv.40; Prismana Snapshots and rotation require Student II; Fantasy Resonance requires Student I. The November 12 update notice, published November 9 and checked November 12, replaces the older racing preview and photo opening time. Start after the version update, then use the mode, track and server tables below. These are announced windows, not live availability or verified spawns.', 'Aniimo Dash 要求40级，Prismana Snapshots 与轮换要求 Student II，Fantasy Resonance 要求 Student I。11月9日发布、11月12日核对的更新公告替代旧竞速预告和摄影开场时间。版本更新后，按下方模式、赛道与服务器表准备；这里是公告窗口，不是实时开放或刷新监测。', 'Aniimo Dash 要求40級，Prismana Snapshots 與輪換要求 Student II，Fantasy Resonance 要求 Student I。11月9日發布、11月12日核對的更新公告替代舊競速預告和攝影開場時間。版本更新後，按下方模式、賽道與伺服器表準備；這裡是公告視窗，不是即時開放或刷新監測。'),
    body: [
      ...getNovemberEventBlocks(locale),
      { t: 'h', c: t('1. Select your server and rotation', '1. 选择服务器与轮换', '1. 選擇伺服器與輪換') },
      { t: 'prismanaSchedule' },
      { t: 'h', c: t('Where can I check the featured form?', '在哪里核对本期指定形态？', '在哪裡核對本期指定形態？') },
      { t: 'p', c: t('Pouchwisp, Royalby, Jeburst and Glameep now have Basic Form records checked November 8. Use the links in the schedule to compare their published roles, skill conditions and traversal abilities. Use the announcement for the named Prismana target and area pair: Basic Form attributes and habitats do not establish Prismana values or exact spawn points.', 'Pouchwisp、Royalby、Jeburst、Glameep 的基础形态记录已于11月8日核验。可从上表进入详情，比较公开定位、技能条件和移动能力。指定 Prismana 目标与区域仍以公告为准：基础形态属性和栖息地不能证明 Prismana 数值或精确刷新点。', 'Pouchwisp、Royalby、Jeburst、Glameep 的基礎形態記錄已於11月8日核驗。可從上表進入詳情，比較公開定位、技能條件和移動能力。指定 Prismana 目標與區域仍以公告為準：基礎形態屬性和棲息地不能證明 Prismana 數值或精確刷新點。') },
      { t: 'link', href: sourceById.get('aniimo-s1-part-two-2026-10-27')!.url, c: t('Open the official Part 2 announcement for featured forms and areas', '在官方后半段公告核对指定形态与区域', '在官方後半段公告核對指定形態與區域') },
      { t: 'link', href: '/dex/089', c: t('Glameep: updated Basic Form record at its existing URL', 'Glameep：保留原网址的基础形态更新', 'Glameep：保留原網址的基礎形態更新') },
      { t: 'link', href: '/guide/aniimo-forms-explained', c: t('Distinguish form identity from Sparkling appearance', '区分形态身份与 Sparkling 外观', '區分形態身分與 Sparkling 外觀') },
      { t: 'p', c: t('The first four windows feature one Prismana Form each. November 30 to December 7 repeats all four together in their corresponding area pairs. The two areas on a row are listed alternatives, not an instruction to visit both or a guaranteed spawn point. Americas uses the announcement\'s UTC-4 offset; do not silently substitute your local daylight-saving rules.', '前四期各对应一种 Prismana 形态，11月30日至12月7日四者在各自对应区域同时出现。同行两个区域是公告列出的地点，不代表必须都去，也不保证固定刷新点。美洲服保留公告 UTC-4，不能自行套用设备所在地的夏令时规则。', '前四期各對應一種 Prismana 形態，11月30日至12月7日四者在各自對應區域同時出現。同列兩個區域是公告列出的地點，不代表必須都去，也不保證固定刷新點。美洲服保留公告 UTC-4，不能自行套用裝置所在地的夏令時間規則。') },
      { t: 'h', c: t('2. Check the entry requirement before travelling', '2. 出发前核对参与条件', '2. 出發前核對參與條件') },
      { t: 'li', c: t('Reach Student II for Vein Abundance. Its overall window is October 30 04:00 to December 7 03:59 in each announced server timezone.', 'Vein Abundance 要求 Student II；整体活动窗口为各服公告时区10月30日04:00至12月7日03:59。', 'Vein Abundance 要求 Student II；整體活動窗口為各服公告時區10月30日04:00至12月7日03:59。') },
      { t: 'li', c: t('Confirm the named region is accessible in your current story progress. The update says Whisperwake content unlocks after prerequisite story quests, but does not provide a complete quest-by-quest route here. A rank requirement is not proof the area is already unlocked.', '确认当前主线已能进入指定区域。更新公告只说明完成前置剧情后开放 Whisperwake 内容，没有提供完整逐步任务路线；达到活动称号不等于已经解锁地图。', '確認目前主線已能進入指定區域。更新公告只說明完成前置劇情後開放 Whisperwake 內容，沒有提供完整逐步任務路線；達到活動稱號不等於已經解鎖地圖。') },
      { t: 'li', c: t('During the designated phase, the first three Nurture actions each weekend have an increased Nova Stage appearance probability; picking Veinfruit increases regional Prismatic Energy growth by an additional 50%. This is not a 50% catch rate or a guaranteed Prismana encounter.', '指定阶段每周末前3次 Nurture 的 Nova Stage 出现概率提高，采集 Veinfruit 时区域 Prismatic Energy 增长额外增加50%。这不是50%捕获率，也不是必出 Prismana。', '指定階段每週末前3次 Nurture 的 Nova Stage 出現機率提高，採集 Veinfruit 時區域 Prismatic Energy 增長額外增加50%。這不是50%捕獲率，也不是必出 Prismana。') },
      { t: 'h', c: t('3. Separate this rotation from photo events', '3. 不要把轮换与摄影活动混为一谈', '3. 不要把輪換與攝影活動混為一談') },
      { t: 'p', c: t('All three activities below require Student II. Date ranges normally begin at 04:00 and end at 03:59 in the announced server clock: APAC UTC+8, Europe UTC+0, Americas UTC-4. Exception: Prismana Snapshots phase 1 begins after the November 12 version update, not at 04:00. Phases 2 and 3 retain the 04:00 opening. Confirm the phase target in the event panel; a rotation target is not proof of the photo target.', '下列三项均要求 Student II。日期段通常从首日04:00至末日03:59，按亚太 UTC+8、欧洲 UTC+0、美洲 UTC-4。例外是 Prismana Snapshots 第一期在11月12日版本更新后开始，不是04:00；第二、三期仍从04:00开始。本期摄影目标请看活动面板，不能直接用轮换目标代替。', '下列三項均要求 Student II。日期段通常從首日04:00至末日03:59，按亞太 UTC+8、歐洲 UTC+0、美洲 UTC-4。例外是 Prismana Snapshots 第一期在11月12日版本更新後開始，不是04:00；第二、三期仍從04:00開始。本期攝影目標請看活動面板，不能直接用輪換目標代替。') },
      { t: 'table', head: [t('Activity', '活动', '活動'), t('Phase 1', '第一期', '第一期'), t('Phase 2', '第二期', '第二期'), t('Phase 3', '第三期', '第三期')], rows: [
        ["Who's That Aniimo?", '2026-10-30 – 2026-11-06', '2026-11-13 – 2026-11-20', '2026-11-27 – 2026-12-04'],
        ['Prismana Snapshots', t('After 2026-11-12 update – 2026-11-16 03:59', '2026-11-12 更新后 – 2026-11-16 03:59', '2026-11-12 更新後 – 2026-11-16 03:59'), '2026-11-16 04:00 – 2026-11-23 03:59', '2026-11-23 04:00 – 2026-11-30 03:59'],
        ['Glamour Star', '2026-11-06 – 2026-11-13', '2026-11-20 – 2026-11-27', '2026-12-04 – 2026-12-11'],
      ] },
      { t: 'p', c: t('For example, the November 9 Royalby rotation starts at Beijing time 04:00 on APAC, 12:00 on Europe and 16:00 on Americas. Those are three different instants. The rotation selector above follows these offsets; the photo and contest table is a published schedule, not a live availability indicator.', '例如11月9日 Royalby 轮换开始，换算为北京时间分别是：亚太服04:00、欧洲服12:00、美洲服16:00，三者不是同一时刻。上方轮换选择器按这些偏移计算；摄影与参赛日期表是公告排期，不是实时开放监控。', '例如11月9日 Royalby 輪換開始，換算為北京時間分別是：亞太服04:00、歐洲服12:00、美洲服16:00，三者不是同一時刻。上方輪換選擇器按這些偏移計算；攝影與參賽日期表是公告排期，不是即時開放監控。') },
      { t: 'table', head: [t('Activity', '活动', '活動'), t('What counts', '有效操作', '有效操作'), t('Common mismatch', '常见误区', '常見誤區')], rows: [
        ['Vein Abundance', t('Visit the scheduled area and check the featured Prismana Form.', '按排期进入区域并核对指定 Prismana 形态。', '按排期進入區域並核對指定 Prismana 形態。'), t('A basic form or a different week does not establish the featured encounter.', '基础形态或其他周的记录不能证明本期目标出现。', '基礎形態或其他週的紀錄不能證明本期目標出現。')],
        ["Who's That Aniimo?", t('Submit the same form as the phase silhouette; qualifying existing album photos can count. Photographing before the full reveal can earn an extra observation reward.', '提交与本期剪影相同形态的照片，符合条件的相册旧照片也可使用；完全揭晓前成功拍摄可获得额外观察奖励。', '提交與本期剪影相同形態的照片，符合條件的相簿舊照片也可使用；完全揭曉前成功拍攝可獲得額外觀察獎勵。'), t('Own, other-player or wild Aniimo can count; Holo-Battle Sim and Sanctum targets cannot be submitted. October 30 patch marks Gachapus recognition fixed.', '自己、其他玩家或野外伊莫均可；Holo-Battle Sim 和 Sanctum 内目标不能提交。10月30日补丁标记已修复 Gachapus 识别。', '自己、其他玩家或野外伊莫均可；Holo-Battle Sim 和 Sanctum 內目標不能提交。10月30日補丁標記已修正 Gachapus 識別。')],
        ['Prismana Snapshots', t('Use the in-game camera on the phase’s designated Prismana Form. Each of the first five different regular Sparkling types earns its photo reward; five total unlock an additional completion reward.', '用游戏内相机拍摄本期指定 Prismana 形态。前5种不同普通 Sparkling 类型各有拍摄奖励，累计5种另获完成奖励。', '用遊戲內相機拍攝本期指定 Prismana 形態。前5種不同普通 Sparkling 類型各有拍攝獎勵，累計5種另獲完成獎勵。'), t('Dazzling Sparkling and Shadow Sparkling do not count toward those five. Repeating a type or photographing regular types beyond the first five gives no further progress or reward.', 'Dazzling Sparkling 与 Shadow Sparkling 不计入这5种。重复类型或超过前5种的普通类型均不再增加进度或奖励。', 'Dazzling Sparkling 與 Shadow Sparkling 不計入這5種。重複類型或超過前5種的普通類型均不再增加進度或獎勵。')],
        ['Glamour Star', t('Select Aniimo and coordinate Accessories for the announced phase theme, register, then compare the score with the reward thresholds.', '按本期公布主题选择伊莫并搭配 Accessories，完成报名，再按得分门槛核对奖励。', '按本期公布主題選擇伊莫並搭配 Accessories，完成報名，再按得分門檻核對獎勵。'), t('Repeat entries are allowed, but each reward is claimable only once per phase. No verified current theme, scoring formula or guaranteed high-score outfit is supplied here.', '允许重复参赛，但每期每项奖励只能领取一次；本站未核验当期主题、评分公式或必得高分搭配。', '允許重複參賽，但每期每項獎勵只能領取一次；本站未核驗當期主題、評分公式或必得高分搭配。')],
      ] },
      { t: 'p', c: t('Special Snapshots has two reward layers: the first Dazzling Sparkling and first Shadow Sparkling photo each earn that type’s photo reward. Either also unlocks one extra Special Snapshot reward, shared once per phase, not one extra for each type. Before travelling, check the target form and missing regular types; before spending on Glamour Star, check the actual theme and thresholds.', '特殊摄影分两层：首次拍到 Dazzling Sparkling、首次拍到 Shadow Sparkling，各可领对应类型的拍摄奖励；拍到任意一种，还可领每期共享一次的额外 Special Snapshot 奖励，不是两种各有一次额外奖励。出发前核对目标形态和缺少的普通类型；Glamour Star 消耗前先看实际主题与门槛。', '特殊攝影分兩層：首次拍到 Dazzling Sparkling、首次拍到 Shadow Sparkling，各可領對應類型的拍攝獎勵；拍到任意一種，還可領每期共用一次的額外 Special Snapshot 獎勵，不是兩種各有一次額外獎勵。出發前核對目標形態和缺少的普通類型；Glamour Star 消耗前先看實際主題與門檻。') },
      { t: 'link', href: sourceById.get('aniimo-s1-part-two-2026-10-27')!.url, c: t('November 6 schedule review: read the original October 29 event announcement', '11月6日复核排期：查看10月29日活动公告原文', '11月6日複核排期：查看10月29日活動公告原文') },
      { t: 'link', href: '/guide/aniimo-launch-checklist-known-issues', c: t('Photo recognition, missing models or blocked quests: check the dated fixes', '照片不识别、模型消失或任务卡住：查看对应修复', '照片不識別、模型消失或任務卡住：查看對應修正') },
      { t: 'link', href: '/guide/aniimo-catching-guide', c: t('Prepare a conditional capture estimate, not a guaranteed catch', '准备条件捕获估算，而不是保证捕获', '準備條件捕獲估算，而不是保證捕獲') },
      { t: 'h', c: t('Historical windows, not current alternatives', '历史窗口，不是当前可选活动', '歷史窗口，不是目前可選活動') },
      { t: 'table', head: [t('Historical activity', '历史活动', '歷史活動'), t('Ended window (UTC+8)', '已结束窗口（UTC+8）', '已結束窗口（UTC+8）')], rows: [
        ['Melloblum', t('Ended: Sep 28 04:00 - Oct 5 03:59', '已结束：9/28 04:00 - 10/5 03:59', '已結束：9/28 04:00 - 10/5 03:59')],
        ['Waleetle', '2026-10-05 04:00 - 2026-10-12 03:59'],
        ['Journey Chronicles', '2026-10-01 04:00 - 2026-10-29 03:59'],
      ] },
      { t: 'quote', c: t('S1 Part 2 announcement published October 27; October 30 patch and schedule checked November 1, 2026. Area names retain the official English wording to avoid inventing translated map labels. No coordinates, spawn timer or encounter rate is verified here.', 'S1 后半段公告发布于10月27日；排期和10月30日补丁核对于2026年11月1日。区域名保留官方英文，避免自拟地图译名。未核验坐标、刷新计时或遭遇概率。', 'S1 後半段公告發布於10月27日；排期和10月30日補丁核對於2026年11月1日。區域名保留官方英文，避免自擬地圖譯名。未核驗座標、刷新計時或遭遇機率。') },
    ],
  };
  if (slug !== 'aniimo-launch-checklist-known-issues') return undefined;
  return {
    title: t('Aniimo November 12 Maintenance, Whirlbite Reset & Fixes', '伊莫11月12日维护、Whirlbite 重置与问题排查', '伊莫11月12日維護、Whirlbite 重置與問題排查'),
    subtitle: t('Check the maintenance window, Whirlbite reset eligibility and deadline, then match mobile or console symptoms to dated fixes.', '先核对维护窗口、Whirlbite 重置资格与截止，再按手机或主机症状排查。', '先核對維護視窗、Whirlbite 重置資格與截止，再按手機或主機症狀排查。'),
    tag: t('Known issues', '问题排查', '問題排查'),
    lead: t('If login fails on November 12, check scheduled maintenance first. Then match your platform and exact symptom. The November 12 update notice was published November 9 and checked November 12; older patches below retain their own evidence dates. Resetting eligible Whirlbite removes corresponding progression effects: read the scope before acting. These are official announcements and scoped next checks, not client tests or a live unresolved-bug list.', '11月12日无法登录时，先核对计划维护，再匹配平台和准确症状。11月12日更新公告发布于11月9日、核对于11月12日；下方旧补丁保留各自核验日期。符合资格的 Whirlbite 重置会撤销对应成长效果，操作前先看范围。这里是官方公告与对应核对步骤，不是客户端实测或实时未解决 Bug 清单。', '11月12日無法登入時，先核對計畫維護，再符合平台和準確症狀。11月12日更新公告發布於11月9日、核對於11月12日；下方舊補丁保留各自核驗日期。符合資格的 Whirlbite 重置會撤銷對應成長效果，操作前先看範圍。這裡是官方公告與對應核對步驟，不是客戶端實測或即時未解決 Bug 清單。'),
    body: [
      ...getNovember12Blocks(locale),
      ...getNovemberSupportBlocks(locale),
      ...getNovemberFixBlocks(locale),
      { t: 'h', c: t('November 5: choose the symptom, not a generic workaround', '11月5日：按症状选择检查项', '11月5日：按症狀選擇檢查項') },
      { t: 'link', href: sourceById.get('aniimo-patch-1-1-3880756-2026-11-05')!.url, c: t('Official v1.1.3880756.0: November 5, checked November 6', '官方 v1.1.3880756.0：11月5日发布，11月6日核对', '官方 v1.1.3880756.0：11月5日發布，11月6日核對') },
      { t: 'table', head: [t('Symptom', '症状', '症狀'), t('What the patch fixes', '补丁修复范围', '補丁修正範圍'), t('Check after updating', '更新后核对', '更新後核對')], rows: [
        [t('PS5: invitation received, unable to team up', 'PS5：收到邀请却无法组队', 'PS5：收到邀請卻無法組隊'), t('Failure to team up after receiving an invitation on PS5.', 'PS5 收到邀请后组队失败。', 'PS5 收到邀請後組隊失敗。'), t('Retry the invitation on the updated client. If it persists, record both platforms, server and error; this does not prove every cross-platform pairing works.', '更新后重试邀请；仍失败则记录双方平台、服务器与报错，不能由此证明任意跨平台组合都可用。', '更新後重試邀請；仍失敗則記錄雙方平台、伺服器與報錯，不能由此證明任意跨平台組合都可用。')],
        [t('Storage Box selection reverts after teleport', '传送后 Storage Box 选择回退', '傳送後 Storage Box 選擇回退'), t('Switching boxes then teleporting reverted to the previous box.', '切换箱子后传送，会回到先前箱子的状态。', '切換箱子後傳送，會回到先前箱子的狀態。'), t('Compare the selected box before and after teleport. A selection reset alone is not proof of missing Aniimo; do not release or replace them to test it.', '对照传送前后所选箱子；选择回退本身不能证明伊莫丢失，不要放生或替换来试错。', '對照傳送前後所選箱子；選擇回退本身不能證明伊莫遺失，不要放生或替換來試錯。')],
        ['Holo Training Ace / Windchaser Stamps', t('Achievement unlock after the current season’s highest training difficulty; Stamp Rush earning while below the weekly limit.', '当季最高训练难度后的成就解锁；未达周上限却无法在 Stamp Rush 获取印章。', '當季最高訓練難度後的成就解鎖；未達週上限卻無法在 Stamp Rush 取得印章。'), t('Check achievement status or this week’s total separately. Neither automatic retroactive rewards nor removal of the weekly limit is announced.', '分别核对成就状态或本周累计；公告没有承诺自动追溯补发，也没有取消周上限。', '分別核對成就狀態或本週累計；公告沒有承諾自動追溯補發，也沒有取消週上限。')],
        [t('Controller: long mail or Aniimo emotes', '手柄：长邮件或伊莫表情', '控制器：長郵件或伊莫表情'), t('Reading lengthy mail with a controller; conflicting button assignments preventing emote selection.', '手柄无法阅读长邮件；按键冲突导致无法选择伊莫表情。', '控制器無法閱讀長郵件；按鍵衝突導致無法選擇伊莫表情。'), t('Retest the same screen and note controller/platform. This is not a Steam Deck support certification or a fix for every input issue.', '复测同一界面并记录手柄与平台；不是 Steam Deck 支持认证，也不是所有输入问题的通用修复。', '複測同一介面並記錄控制器與平台；不是 Steam Deck 支援認證，也不是所有輸入問題的通用修正。')],
        [t('Evolution buttons or Gravity Pull switching missing', '进化按钮缺失或 Gravity Pull 无法切换', '進化按鈕缺失或 Gravity Pull 無法切換'), t('Missing evolution-screen buttons; inability to switch flying Aniimo during Gravity Pull.', '进化界面部分按钮缺失；Gravity Pull 赛道无法切换飞行伊莫。', '進化介面部分按鈕缺失；Gravity Pull 賽道無法切換飛行伊莫。'), t('Check the restored action on the same target/course. Button restoration does not waive evolution materials or unlock every flying ability.', '在同一目标或赛道核对操作；恢复按钮不等于免除进化材料，也不等于解锁所有飞行能力。', '在同一目標或賽道核對操作；恢復按鈕不等於免除進化材料，也不等於解鎖所有飛行能力。')],
        [t('Story water column / Bloom prompt', '剧情水柱／Bloom 提示', '劇情水柱／Bloom 提示'), t('An unintended climbable water column in The Challenge of Fighting Upstream!; incorrect Bloom prompt before its Branch unlocked.', 'The Challenge of Fighting Upstream! 中本不可攀爬水柱却可攀爬；Branch 未解锁时 Bloom 交互提示错误。', 'The Challenge of Fighting Upstream! 中本不可攀爬水柱卻可攀爬；Branch 未解鎖時 Bloom 互動提示錯誤。'), t('Follow the current objective and Branch state. The November 5 water-column fix is distinct from October 30 Waterfall Climb progression fixes; not all columns are climbable.', '按当前任务目标与 Branch 状态判断；11月5日水柱修复不同于10月30日 Waterfall Climb 进度修复，不是所有水柱都能爬。', '按目前任務目標與 Branch 狀態判斷；11月5日水柱修正不同於10月30日 Waterfall Climb 進度修正，不是所有水柱都能爬。')],
        [t('Nimbi, Home furniture or Sherro Hydro Roll', 'Nimbi、家园家具或 Sherro Hydro Roll', 'Nimbi、家園家具或 Sherro Hydro Roll'), t('Nimbi display in Night Parade, some Home furniture displays, and no puddle when Hydro Roll was interrupted.', 'Night Parade 中 Nimbi 显示、部分家园家具显示、Hydro Roll 被打断时未生成水洼。', 'Night Parade 中 Nimbi 顯示、部分家園家具顯示、Hydro Roll 被打斷時未產生水窪。'), t('Record the event/object and interruption if it repeats. These fixes do not publish a scent recipe, furniture compensation or new skill multiplier.', '若复现，记录活动、对象与打断条件；这些修复没有公布气味配方、家具补偿或新技能倍率。', '若重現，記錄活動、對象與打斷條件；這些修正沒有公布氣味配方、家具補償或新技能倍率。')],
      ] },
      { t: 'link', href: '/guide/aniimo-progress-account-safety', c: t('Steam/Epic unlink is now available: check the account workflow before using it', 'Steam／Epic 已有解绑入口：操作前核对账号流程', 'Steam／Epic 已有解除綁定入口：操作前核對帳號流程') },
      { t: 'h', c: t('1. Record the symptom before changing anything', '1. 先记录症状，再改设置', '1. 先記錄症狀，再改設定') },
      { t: 'p', c: t('Record platform, device/GPU, client version, server region, the exact task or location, and the message shown. Update through the official launcher/store, restart and retry once. If the symptom persists, report that current-version reproduction instead of assuming the old fix applies. Do not unlink accounts, delete saves or disable security software to test a guess.', '记录平台、设备／显卡、客户端版本、服务器地区、准确任务或地点，以及原始提示。通过官方启动器或商店更新，重启后复测一次。仍有问题时提交当前版本复现记录，不要假定历史修复适用；不要为试错解绑账号、删除存档或关闭安全软件。', '記錄平台、裝置／顯示卡、客戶端版本、伺服器地區、準確任務或地點，以及原始提示。透過官方啟動器或商店更新，重啟後複測一次。仍有問題時提交目前版本重現紀錄，不要假定歷史修正適用；不要為試錯解除帳號綁定、刪除存檔或關閉安全軟體。') },
      { t: 'h', c: t('2. Match a specific October 30 fix', '2. 对照10月30日的具体修复', '2. 對照10月30日的具體修正') },
      { t: 'table', head: [t('Symptom / scope', '症状／范围', '症狀／範圍'), t('Official patch status', '官方补丁状态', '官方補丁狀態'), t('What to check next', '下一步核对', '下一步核對')], rows: [
        ['Waterfall Climb / Touch the mysterious mechanism', t('Marked fixed for The Challenge of Fighting Upstream! progression blocks.', '标记修复 The Challenge of Fighting Upstream! 中的任务阻塞。', '標記修正 The Challenge of Fighting Upstream! 中的任務阻塞。'), t('After updating, retry the same quest objective. Record the objective text if it still fails; this is not a complete quest walkthrough.', '更新后重试同一任务目标；仍失败则记录目标原文，不把这条修复当成完整通关路线。', '更新後重試同一任務目標；仍失敗則記錄目標原文，不把這條修正當成完整通關路線。')],
        ["Who's That Aniimo? / Gachapus", t('Gachapus photo recognition marked fixed.', 'Gachapus 摄影识别标记已修复。', 'Gachapus 攝影識別標記已修正。'), t('Check the requested form first; Holo-Battle Sim and Sanctum photos are ineligible under the event rules.', '先核对指定形态；活动规则不接受 Holo-Battle Sim 或 Sanctum 内目标。', '先核對指定形態；活動規則不接受 Holo-Battle Sim 或 Sanctum 內目標。')],
        ['Dewple Waterfall Form', t('Unlock progression in the Isle of Might waterfall area marked fixed.', 'Isle of Might 瀑布区域的解锁进度问题标记已修复。', 'Isle of Might 瀑布區域的解鎖進度問題標記已修正。'), t('Report the form, exact area and failed step if it persists; do not infer the unlock recipe from this patch.', '若仍失败，提交形态、准确区域与失败步骤；不能从此补丁推断解锁配方。', '若仍失敗，提交形態、準確區域與失敗步驟；不能從此補丁推斷解鎖配方。')],
        [t('Mobile chests under trees / Isle of Might wetland chests', '移动端树下宝箱／Isle of Might 湿地宝箱', '行動裝置樹下寶箱／Isle of Might 濕地寶箱'), t('Specific uncollectable chest issues marked fixed.', '具体宝箱无法收集问题标记已修复。', '具體寶箱無法收集問題標記已修正。'), t('Retest the same chest and include platform plus location; not every inaccessible chest is the same bug.', '复测同一宝箱并附平台、地点；不是所有无法接近的宝箱都属于此 Bug。', '複測同一寶箱並附平台、地點；不是所有無法接近的寶箱都屬於此 Bug。')],
        [t('Umbral / Sparkling models missing; hue switching display', 'Umbral／Sparkling 模型缺失、切换颜色不显示', 'Umbral／Sparkling 模型缺失、切換顏色不顯示'), t('Specific model and Sparkling Hue display failures marked fixed.', '特定模型与 Sparkling Hue 显示故障标记已修复。', '特定模型與 Sparkling Hue 顯示故障標記已修正。'), t('Distinguish a missing model from an incorrect party hue; report the form and screen without releasing the Aniimo.', '区分模型消失与队伍颜色错误；记录形态和界面，不要放生伊莫来试错。', '區分模型消失與隊伍顏色錯誤；記錄形態和介面，不要放生伊莫來試錯。')],
        [t('Xbox PC settings / cutscene audio', 'Xbox PC 设置／过场音频', 'Xbox PC 設定／過場音訊'), t('Missing settings including Variable Rate Shading marked fixed; cutscene audio playback improved.', '含 Variable Rate Shading 的设置缺失标记修复；过场音频播放改善。', '含 Variable Rate Shading 的設定缺失標記修正；過場音訊播放改善。'), t('Do not equate an audio fix with a universal FPS fix. Record device, scene and before/after behavior.', '音频修复不等于通用 FPS 修复；记录设备、场景与前后变化。', '音訊修正不等於通用 FPS 修正；記錄裝置、場景與前後變化。')],
      ] },
      { t: 'h', c: t('3. Loading freezes, black screens or a missing character', '3. 加载卡住、黑屏或角色消失', '3. 載入卡住、黑畫面或角色消失') },
      { t: 'p', c: t('The official S1 Part 2 thread lists a loading hotfix and specific freeze, black-screen and invisible-character fixes, while retaining an older Known Issues section. Treat duplicate entries as a dated record, not proof the issue is both fixed and still universally present. If it repeats after updating, capture the last screen reached, server and reproduction steps. No universal graphics preset or guaranteed performance workaround has been verified here.', '官方 S1 后半段问题帖列有加载热修复，以及特定卡死、黑屏、角色不可见修复，同时保留旧 Known Issues。重复条目是带日期的记录，不能据此认定问题已全面解决或所有玩家仍受影响。更新后仍出现时，记录最后到达的界面、服务器与复现步骤；本站没有核验通用画质方案或保证有效的性能修复。', '官方 S1 後半段問題帖列有載入熱修正，以及特定卡死、黑畫面、角色不可見修正，同時保留舊 Known Issues。重複條目是帶日期的紀錄，不能據此認定問題已全面解決或所有玩家仍受影響。更新後仍出現時，記錄最後到達的介面、伺服器與重現步驟；本站沒有核驗通用畫質方案或保證有效的效能修正。') },
      { t: 'h', c: t('4. Send a useful private support report', '4. 准备有用的私密支持工单', '4. 準備有用的私密支援工單') },
      { t: 'p', c: t('Use in-game Customer Support or aniimo_support@aniimo.com, as listed in the official thread. Include platform/device, server, client version, exact location/task, error text, a redacted screenshot and reproducible steps. Supply UID and requested logs only through official private support; inspect attachments for account details and local paths. Do not post credentials, full logs or account identifiers in public comments.', '按官方问题帖使用游戏内 Customer Support 或 aniimo_support@aniimo.com。提供平台设备、服务器、客户端版本、准确地点任务、报错原文、脱敏截图与复现步骤。UID 和官方要求的日志仅通过官方私密支持提供；检查附件中的账号资料与本地路径，不要在公开评论发布凭据、完整日志或账号标识。', '按官方問題帖使用遊戲內 Customer Support 或 aniimo_support@aniimo.com。提供平台裝置、伺服器、客戶端版本、準確地點任務、報錯原文、去識別截圖與重現步驟。UID 和官方要求的日誌僅透過官方私密支援提供；檢查附件中的帳號資料與本機路徑，不要在公開留言發布憑證、完整日誌或帳號識別資料。') },
      { t: 'link', href: '/guide/aniimo-prismana-event-tracker', c: t('Check event time, eligibility and photo rules before treating it as a bug', '先核对活动时间、资格和摄影规则，再判断是否故障', '先核對活動時間、資格和攝影規則，再判斷是否故障') },
      { t: 'link', href: '/guide/aniimo-progress-account-safety', c: t('Missing progress or wrong account: use the account-safety checklist', '进度缺失或账号不对：使用账号安全清单', '進度缺失或帳號不對：使用帳號安全清單') },
      { t: 'h', c: t('Historical support references: match version and symptom first', '历史支持记录：先匹配版本与症状', '歷史支援紀錄：先匹配版本與症狀') },
      { t: 'p', c: t('The October 15 v1.0.3732728.0 patch and Dev Feedback | Oct 13 remain historical references, not the latest patch. Earlier Steam Input, F10, error107 and account-recovery instructions below apply only to their documented scope. Do not assume a September compensation or time-limited recovery process is still available.', '10月15日 v1.0.3732728.0 与 Dev Feedback | Oct 13 保留为历史来源，不是最新补丁。下方较早的 Steam Input、F10、error107 和账号恢复说明只适用于记录范围，不要假设9月补偿或限时恢复流程仍可使用。', '10月15日 v1.0.3732728.0 與 Dev Feedback | Oct 13 保留為歷史來源，不是最新補丁。下方較早的 Steam Input、F10、error107 和帳號恢復說明只適用於紀錄範圍，不要假設9月補償或限時恢復流程仍可使用。') },
    ],
  };
}
